Matching Ayahs
- = អាលីហ្វ, ឡាម, មីម. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = អ្នកទាំងនោះហើយគឺស្ថិតនៅលើផ្លូវត្រឹមត្រូវពីម្ចាស់របស់ពួកគេ ហើយអ្នកទាំងនោះហើយគឺជាអ្នកជោគជ័យ។ 2:5; 31:5
- = ឱកូនចៅអ៊ីស្រាអែលអើយ! ចូរនឹកចាំពីឧបការកិច្ចរបស់ខ្ញុំ ដែលខ្ញុំបានប្រទានមកលើពួកអ្នក និងការដែលខ្ញុំបានលើកតម្កើងពួកអ្នកឱ្យខ្ពង់ខ្ពស់ជាងសកលលោក (ប្រជាជាតិ) ទាំងឡាយ។ 2:47; 2:122
- = នោះជាសាសន៍មួយដែលបានកន្លងផុតទៅហើយ។ អ្វីដែលពួកគេបានសាងបានមកដល់ពួកគេ ហើយអ្វីដែលពួកអ្នកបានសាងបានមកដល់ពួកអ្នក។ ហើយពួកអ្នកនឹងមិនត្រូវបានសួរអំពីអ្វីដែលពួកគេធ្លាប់ប្រព្រឹត្តនោះឡើយ។ 2:134; 2:141
- = ពួកគេនឹងស្ថិតនៅក្នុងនោះជារៀងរហូត។ ទណ្ឌកម្មនឹងមិនត្រូវបានស្រាលបន្ថយឱ្យពួកគេឡើយ ហើយពួកគេក៏នឹងមិនត្រូវបានពន្យារពេលដែរ។ 2:162; 3:88
- = លើកលែងតែអ្នកដែលបានតូបះបន្ទាប់ពីនោះ ហើយបានកែខ្លួនឡើងវិញ។ ព្រោះពិតប្រាកដណាស់ អល់ឡោះជាអ្នកអភ័យទោស ជាអ្នកមេត្តាប្រណីតាបំផុត។ 3:89; 24:5
- = ប៉ុន្តែពួកដែលប្រឆាំង និងបានបដិសេធនឹងភស្តុតាងទាំងឡាយរបស់យើង – អ្នកទាំងនោះហើយជាអ្នកនៅក្នុងឋាននរក។ 5:10; 5:86
- = ហើយគ្មានភស្តុតាងណាមួយក្នុងចំណោមភស្តុតាងរបស់ម្ចាស់របស់ពួកគេបានមកដល់ពួកគេទេ លើកលែងតែពួកគេបែរចេញពីវា។ 6:4; 36:46
- = ហើយពិតប្រាកដណាស់ មានអ្នកនាំសារជាច្រើនត្រូវបានគេចំអកឱ្យអស់សំណើចមុនអ្នក ប៉ុន្តែពួកដែលចំអកឱ្យគេ ត្រូវបានអ្វីដែលពួកគេធ្លាប់ចំអកនោះព័ទ្ធជុំវិញ។ 6:10; 21:41
- = ចូរអ្នក(មូហាំម៉ាត់)ពោលថាៈ «ពិតប្រាកដណាស់ ខ្ញុំខ្លាចទណ្ឌកម្មនៃថ្ងៃដ៏ធំធេង ប្រសិនបើខ្ញុំមិនស្តាប់បង្គាប់ម្ចាស់របស់ខ្ញុំ»។ 6:15; 39:13
- = ដូច្នេះ ការរញ្ជួយដីបានចាប់យកពួកគេ ហើយពួកគេបានក្លាយជាសាកសពដួលដេកនៅក្នុងផ្ទះរបស់ពួកគេ។ 7:78; 7:91
- = ដូច្នេះ គាត់(មូសា)បានទម្លាក់ដំបងរបស់គាត់ ហើយស្រាប់តែវាក្លាយជាពស់ដ៏ច្បាស់លាស់មួយ។ 7:107; 26:32
- = ហើយគាត់បានដកដៃរបស់គាត់ចេញ ស្រាប់តែវាភ្លឺរលោងសសម្រាប់អ្នកដែលបានឃើញ។ 7:108; 26:33
- = ពួកគេបាននិយាយថាៈ «យើងបានជឿលើម្ចាស់នៃសកលលោកទាំងឡាយ»។ 7:121; 26:47
- = ម្ចាស់របស់មូសា និងហារូន។ 7:122; 26:48
- = ហើយខ្ញុំនឹងពន្យារពេលឱ្យពួកគេ។ ពិតប្រាកដណាស់ ផែនការរបស់ខ្ញុំគឺមាំមួន។ 7:183; 68:45
- = ទ្រង់ជាអ្នកដែលបានបញ្ជូនអ្នកនាំសាររបស់ទ្រង់ជាមួយនឹងការណែនាំ និងសាសនាដ៏ពិត ដើម្បីធ្វើឱ្យវាលើសលប់លើសាសនាទាំងអស់ ទោះបីពួកអ្នកដែលចាត់ទុកដៃគូឱ្យទ្រង់មិនពេញចិត្តក៏ដោយ។ 9:33; 61:9
- = ឱណាពីអើយ! ចូរអ្នកតស៊ូប្រឆាំងនឹងពួកអ្នកគ្មានជំនឿ និងពួកពុតត្បុត ហើយចូរអ្នកធ្វើយ៉ាងម៉ឺងម៉ាត់ចំពោះពួកគេ។ ហើយទីជំរករបស់ពួកគេគឺឋាននរកជាហន់នៈ ហើយវាជាទីកន្លែងវិលត្រឡប់ដ៏អាក្រក់បំផុត! 9:73; 66:9
- = ហើយពួកគេនិយាយថាៈ «ការសន្យានេះនឹងកើតឡើងនៅពេលណា ប្រសិនបើពួកអ្នកជាអ្នកពិតប្រាកដមែន?» 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = ហើយពិតប្រាកដណាស់ យើងបានបញ្ជូនមូសាជាមួយនឹងភស្តុតាងរបស់យើង និងអំណាចដ៏ច្បាស់លាស់។ 11:96; 40:23
- = ហើយពិតប្រាកដណាស់ យើងបានប្រទានគម្ពីរដល់មូសា ប៉ុន្តែគេបានខ្វែងគំនិតគ្នាក្នុងរឿងនោះ។ ហើយប្រសិនបើគ្មានពាក្យណាមួយបានកំណត់ទុកជាមុនពីម្ចាស់របស់អ្នកទេ ការសម្រេចចិត្តនឹងត្រូវបានធ្វើឡើងរវាងពួកគេ។ ហើយពិតប្រាកដណាស់ ពួកគេស្ថិតក្នុងការសង្ស័យយ៉ាងខ្លាំងអំពីវា។ 11:110; 41:45
- = នោះមិនមែនជាការលំបាកសម្រាប់អល់ឡោះទេ។ 14:20; 35:17
- = «ហើយនៅពេលដែលខ្ញុំបានបង្កើតគាត់(អាដាម)ឱ្យស្អាតឥតខ្ចោះ ហើយបានផ្លុំវិញ្ញាណរបស់ខ្ញុំចូលទៅក្នុងគាត់ ចូរពួកអ្នកក្រាបចុះចំពោះគាត់»។ 15:29; 38:72
- = ដូច្នេះ ពួកម៉ាឡាអ៊ីកាត់ទាំងអស់បានក្រាបចុះ។ 15:30; 38:73
- = (អល់ឡោះ) មានបន្ទូលថាៈ «ដូច្នេះ ចូរអ្នកចេញពីវាទៅ ព្រោះពិតប្រាកដណាស់ អ្នកគឺជាអ្នកដែលត្រូវបានបណ្តេញចេញ»។ 15:34; 38:77
- = (អ៊ីប្លីស) បាននិយាយថាៈ «ម្ចាស់របស់ខ្ញុំអើយ! ដូច្នេះ សូមទ្រង់ពន្យារពេលឱ្យខ្ញុំរហូតដល់ថ្ងៃដែលពួកគេត្រូវបានគេប្រោសឱ្យរស់ឡើងវិញ»។ 15:36; 38:79
- = (អល់ឡោះ) មានបន្ទូលថាៈ «ដូច្នេះ ពិតប្រាកដណាស់ អ្នកស្ថិតក្នុងចំណោមអ្នកដែលត្រូវបានពន្យារពេល»។ 15:37; 38:80
- = រហូតដល់ថ្ងៃដែលបានកំណត់»។ 15:38; 38:81
- = លើកលែងតែបណ្តាទាសារបស់ទ្រង់ដែលបានជ្រើសរើសក្នុងចំណោមពួកគេ។ 15:40; 38:83
- = ពិតប្រាកដណាស់ អ្នកស្លាប់ព្រលឹង(អ្នកកាន់សេចក្តីកោតខ្លាច)នឹងនៅក្នុងច្បារចម្ការ និងប្រភពទឹកជាច្រើន។ 15:45; 51:15
- = គាត់(អ៊ីព្រហ៊ីម)បាននិយាយថាៈ «ដូច្នេះ តើកិច្ចការរបស់ពួកអ្នកជាអ្វី ឱពួកអ្នកនាំសារអើយ?» 15:57; 51:31
- = ពួកគេបាននិយាយថាៈ «ពិតប្រាកដណាស់ យើងត្រូវបានគេបញ្ជូនទៅកាន់ប្រជាជនមួយដែលជាឧក្រិដ្ឋជន»។ 15:58; 51:32
- = អ្នកដែលមានជំនឿ ហើយមិនបានលាយឡំជំនឿរបស់ពួកគេជាមួយនឹងភាពអយុត្តិធម៌ – អ្នកទាំងនោះនឹងទទួលបានសេចក្តីសុខសាន្ត ហើយពួកគេគឺជាអ្នកទទួលការណែនាំ។ 16:42; 29:59
- = ដើម្បីពួកគេប្រឆាំងនឹងអ្វីដែលយើងបានប្រទានឱ្យពួកគេ។ ដូច្នេះ ចូរពួកអ្នកសប្បាយទៅ ព្រោះពួកអ្នកនឹងដឹង។ 16:55; 30:34
- = បន្ទាប់មក គាត់(ហ្ស៊ុលគរណៃន)បានដើរតាមមួយផ្លូវ។ 18:89; 18:92
- = ចូរអ្នកទៅកាន់ហ្វីរ៉ោន ព្រោះពិតប្រាកដណាស់ គាត់បានបំពានយ៉ាងខ្លាំង។ 20:24; 79:17
- = និងអ្នកដែលចេះថែរក្សាការប្រដាប់ភេទរបស់ពួកគេ(ពីអំពើប្រាសចាកសីលវិជ្ជា)។ 23:5; 70:29
- = លើកលែងតែចំពោះភរិយារបស់ពួកគេ ឬអ្វីដែលដៃស្តាំរបស់ពួកគេទទួលបាន – ព្រោះពិតប្រាកដណាស់ ពួកគេមិនត្រូវស្តីបន្ទោសឡើយ។ 23:6; 70:30
- = ប៉ុន្តែអ្នកណាដែលស្វែងរកក្រៅពីនេះ អ្នកទាំងនោះហើយគឺជាអ្នកបំពាន។ 23:7; 70:31
- = និងអ្នកដែលចេះថែរក្សាវត្ថុដែលគេប្រគល់ឱ្យ និងកិច្ចសន្យារបស់ពួកគេ។ 23:8; 70:32
- = គាត់(នូហ)បាននិយាយថាៈ «ម្ចាស់របស់ខ្ញុំអើយ! សូមទ្រង់ជួយខ្ញុំ ដោយសារពួកគេបានបដិសេធខ្ញុំ»។ 23:26; 23:39
- = តា, ស៊ីន, មីម. 26:1; 28:1
- = នេះគឺជាអាយ៉ាត់ៗនៃគម្ពីរដ៏ច្បាស់លាស់។ 26:2; 28:2
- = ពិតប្រាកដណាស់ នៅក្នុងនោះមានភស្តុតាងមួយ ប៉ុន្តែពួកគេភាគច្រើនមិនមែនជាអ្នកមានជំនឿទេ។ 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = ហើយពិតប្រាកដណាស់ ម្ចាស់របស់អ្នក – ទ្រង់គឺជាអ្នកមានអំណាចខ្លាំងក្លា ជាអ្នកមេត្តាប្រណីតាបំផុត។ 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = ហើយយើងបានធ្វើឱ្យអ្នកផ្សេងទៀតលង់ទឹកស្លាប់។ 26:66; 37:82
- = ពិតប្រាកដណាស់ ខ្ញុំគឺជាអ្នកនាំសារដ៏ទុកចិត្តម្នាក់សម្រាប់ពួកអ្នក។ 26:107; 26:125; 26:143; 26:162; 26:178
- = ដូច្នេះ ចូរពួកអ្នកកោតខ្លាចអល់ឡោះ ហើយចូរពួកអ្នកស្តាប់បង្គាប់ខ្ញុំ។ 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = ហើយខ្ញុំមិនសុំប្រាក់កម្រៃណាមួយពីពួកអ្នកចំពោះការនេះទេ។ ប្រាក់កម្រៃរបស់ខ្ញុំគឺនៅចំពោះតែម្ចាស់នៃសកលលោកទាំងឡាយប៉ុណ្ណោះ។ 26:109; 26:127; 26:145; 26:164; 26:180
- = នៅក្នុងចំការនិងប្រភពទឹក។ 26:147; 44:52
