- តើពួកគេមិនបានធ្វើដំណើរនៅលើផែនដី ហើយមើលទេថាតើលទ្ធផលរបស់អ្នកមុនពួកគេគឺយ៉ាងណា? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِن) 30:9; 35:44; 40:82; 47:10
- សម្រាប់ពួកគេ គឺមានបុណ្យសំណងរបស់ពួកគេនៅឯម្ចាស់របស់ពួកគេ ហើយគ្មានការភ័យខ្លាចលើពួកគេទេ ហើយពួកគេក៏មិនសោកស្តាយដែរ។ (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:62; 2:262; 2:274; 2:277
- ហើយអ្នកដែលមានជំនឿ និងបានប្រព្រឹត្តអំពើល្អ ត្រូវបានបញ្ចូលទៅក្នុងឋានសួគ៌នានា ដែលមានទន្លេនានាហូរកាត់ពីក្រោមវា។ (وَأُدْخِلَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 14:23; 22:14; 22:23; 47:12
- គាត់បាននិយាយថាៈ "ឱក្រុមជនរបស់ខ្ញុំអើយ! ចូរពួកអ្នកគោរពប្រណិប័តន៍អល់ឡោះ ពួកអ្នកគ្មានអាទិទេពណាផ្សេងក្រៅពីទ្រង់ឡើយ តើពួកអ្នកមិនកោតខ្លាចទេឬ?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- ទ្រព្យសម្បត្តិរបស់ពួកគេ និងកូនចៅរបស់ពួកគេ មិនអាចជួយពួកគេឱ្យរួចពីអល់ឡោះបានឡើយ ហើយពួកគេទាំងនោះគឺជា។ (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- ឋានសួគ៌នានា ដែលមានទន្លេនានាហូរកាត់ពីក្រោមវា ដោយពួកគេស្ថិតនៅជាអមតៈនៅទីនោះ ហើយនោះគឺជាជោគជ័យដ៏ធំធេង។ (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- តើដំណឹងរបស់អ្នកមុនពួកគេ គឺប្រជាជនរបស់នួហ អាដ និងសាមូដ មិនបានមកដល់ពួកគេទេឬ? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- តើអ្នកណាខ្លះជាអ្នកជួយរបស់ខ្ញុំ ឆ្ពោះទៅកាន់អល់ឡោះ? ពួកហាវ៉ារីយូន (ពួកសិស្ស) បាននិយាយថាៈ "យើងជាអ្នកជួយរបស់អល់ឡោះ យើងបានមានជំនឿហើយ។" (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- ម្ចាស់របស់អ្នក ទ្រង់ជាអ្នកដឹងច្បាស់បំផុតថា អ្នកណាដែលវង្វេងចេញពីផ្លូវរបស់ទ្រង់ ហើយទ្រង់ជាអ្នកដឹងច្បាស់បំផុតចំពោះអ្នកដែលទទួលការណែនាំ។ (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- នោះគឺដោយសារតែអល់ឡោះ ទ្រង់ជាសេចក្តីពិត ហើយអ្វីដែលពួកគេអំពាវនាវក្រៅពីទ្រង់ គឺជារឿងមិនពិត។ (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- ហើយអ្នកណាដែលស្តាប់បង្គាប់អល់ឡោះ និងអ្នកនាំសាររបស់ទ្រង់ អល់ឡោះនឹងបញ្ចូលគាត់ទៅក្នុងឋានសួគ៌នានា ដែលមានទន្លេនានាហូរកាត់ពីក្រោមវា។ (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- ពិតប្រាកដណាស់ ទ្រង់បានហាមឃាត់ចំពោះពួកអ្នកនូវសត្វងាប់ ឈាម សាច់ជ្រូក និងអ្វីដែលគេសម្លាប់ដោយមិនភ្ជាប់ព្រះនាមអល់ឡោះ។ (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- ថាពួកអ្នកកុំគោរពប្រណិប័តន៍អ្វីក្រៅពីអល់ឡោះឡើយ; ពិតប្រាកដណាស់ ខ្ញុំខ្លាចពួកអ្នកនឹងទទួលទណ្ឌកម្មនៅថ្ងៃដ៏ធំធេង។ (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- នោះគឺជាផ្នែកមួយនៃដំណឹងនៃអាថ៌កំបាំង ដែលយើងបានប្រទានវិវរណៈដល់អ្នក ហើយអ្នកមិនបាននៅជាមួយពួកគេទេ នៅពេលដែលពួកគេសម្រេចចិត្ត។ (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- តើពួកអ្នកភ្ញាក់ផ្អើលឬថា មានការរំលឹកពីម្ចាស់របស់ពួកអ្នក មកតាមរយៈបុរសម្នាក់ក្នុងចំណោមពួកអ្នក ដើម្បីឱ្យគាត់ដាស់តឿនពួកអ្នក? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- ចូរអ្នកនិយាយថាៈ "ពិតប្រាកដណាស់ ខ្ញុំត្រូវបានគេហាមឃាត់មិនឱ្យគោរពប្រណិប័តន៍អ្វីដែលពួកអ្នកអំពាវនាវ ក្រៅពីអល់ឡោះ។" (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- លើកលែងតែចំពោះភរិយារបស់ពួកគេ ឬទាស៊ីដែលដៃស្តាំរបស់ពួកគេកាន់កាប់ ដ្បិតពួកគេមិនត្រូវបានគេបន្ទោសឡើយ។ (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- ដោយសារតែអល់ឡោះបញ្ចូលពេលយប់ទៅក្នុងពេលថ្ងៃ ហើយបញ្ចូលពេលថ្ងៃទៅក្នុងពេលយប់។ (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- ភ្លើង ហើយគាត់បាននិយាយទៅកាន់ក្រុមគ្រួសាររបស់គាត់ថាៈ "ចូរពួកអ្នកស្នាក់នៅចាំសិន ពិតប្រាកដណាស់ ខ្ញុំបានឃើញភ្លើង ប្រហែលជាខ្ញុំអាចនាំយកអ្វីមួយមកឱ្យពួកអ្នកពីវា។" (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- គាត់បាននិយាយថាៈ "ខ្ញុំប្រសើរជាងគាត់ ទ្រង់បានបង្កើតខ្ញុំពីភ្លើង ហើយបង្កើតគាត់ពីដីឥដ្ឋ។" (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- ហើយនៅពេលដែលគេនិយាយទៅកាន់ពួកគេថាៈ "ចូរពួកអ្នកមកកាន់អ្វីដែលអល់ឡោះបានបញ្ចុះ និងកាន់អ្នកនាំសារ។" (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- ហើយចូរអ្នកកុំសោកស្តាយចំពោះពួកគេ ហើយកុំចង្អៀតចិត្តដោយសារតែឧបាយកលរបស់ពួកគេ។ (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- ហើយប្រសិនបើអល់ឡោះប៉ះពាល់អ្នកដោយគ្រោះថ្នាក់អ្វីមួយ នោះគ្មានអ្នកណាអាចបណ្តេញវាចេញបានឡើយ លើកលែងតែទ្រង់ ហើយប្រសិនបើ។ (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- មុនពួកគេ ជំនាន់នានាដែលបានដើរក្នុងទីលំនៅរបស់ពួកគេ។ ពិតប្រាកដណាស់ ក្នុងនោះមានភស្តុតាងជាច្រើន។ (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- ហើយយើងបានដាក់ស្បៃបាំងលើបេះដូងរបស់ពួកគេ ដើម្បីកុំឱ្យពួកគេយល់វា ហើយដាក់ភាពធ្ងន់នៅក្នុងត្រចៀករបស់ពួកគេ ហើយប្រសិនបើ។ (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- ពួកអ្នកនាំសាររបស់ពួកគេបានមកដល់ពួកគេ ជាមួយនឹងភស្តុតាងច្បាស់លាស់ ប៉ុន្តែអល់ឡោះមិនមែនជាអ្នកអយុត្តិធម៌ចំពោះពួកគេទេ ប៉ុន្តែពួកគេជាអ្នកអយុត្តិធម៌ចំពោះខ្លួនឯង។ (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- ហើយនៅលើផែនដី ហើយពួកអ្នកគ្មានអាណាព្យាបាល និងគ្មានអ្នកជួយណាក្រៅពីអល់ឡោះឡើយ។ (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- បន្ទាប់មក ពួកអ្នកនឹងត្រូវបានបញ្ជូនត្រឡប់ទៅកាន់អ្នកដឹងនូវអាថ៌កំបាំង និងអ្វីដែលបើកចំហ ហើយទ្រង់នឹងប្រាប់ពួកអ្នកនូវអ្វីដែលពួកអ្នកបានប្រព្រឹត្ត។ (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ពេលយប់ ដើម្បីឱ្យពួកអ្នកសម្រាកនៅក្នុងនោះ និងពេលថ្ងៃ ដើម្បីឱ្យពួកអ្នកមើលឃើញ។ ពិតប្រាកដណាស់ ក្នុងនោះមានភស្តុតាងជាច្រើន សម្រាប់ប្រជាជនដែលចេះគិតពិចារណា។ (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- ហើយអ្វីដែលត្រូវបានបញ្ចុះមកកាន់អ្នកពីម្ចាស់របស់អ្នក នឹងបង្កើនចំពោះពួកគេភាគច្រើននូវការប្រឆាំង និងការមិនជឿ។ (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- គាត់បាននិយាយថាៈ "ឱក្រុមជនរបស់ខ្ញុំអើយ! តើពួកអ្នកយល់យ៉ាងណាដែរ ប្រសិនបើខ្ញុំស្ថិតលើភស្តុតាងច្បាស់លាស់មួយពីម្ចាស់របស់ខ្ញុំ ហើយទ្រង់បានប្រទានឱ្យខ្ញុំ។" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- ហើយពួកគេនិយាយថាៈ "ហេតុអ្វីបានជាគេមិនបានបញ្ចុះភស្តុតាងមួយមកលើគាត់ពីម្ចាស់របស់គាត់?" ចូរអ្នកនិយាយថាៈ "ពិតប្រាកដណាស់។" (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- មុនពេលដែលថ្ងៃមួយមកដល់ ដែលគ្មានការបដិសេធ (អាចរារាំង) ពីអល់ឡោះឡើយ។ (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- នោះគឺជាព្រះគុណរបស់អល់ឡោះ ដែលទ្រង់ប្រទានវាដល់អ្នកណាដែលទ្រង់សព្វព្រះហឫទ័យ ហើយអល់ឡោះជាម្ចាស់នៃព្រះគុណដ៏ធំធេង។ (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- ហើយពិតប្រាកដណាស់ នៅក្នុងសត្វពាហនៈទាំងឡាយនោះ គឺពិតជាមានមេរៀនមួយសម្រាប់ពួកអ្នក យើងផ្តល់ឱ្យពួកអ្នកផឹកនូវអ្វីដែលនៅក្នុងពោះរបស់វា។ (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- ថានោះគឺជាសេចក្តីពិតពីម្ចាស់របស់ពួកគេ ហើយអល់ឡោះមិនមែនជាអ្នកធ្វេសប្រហែសចំពោះអ្វីដែលពួកគេប្រព្រឹត្តនោះឡើយ។ (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- ពីមុខពួកគេ និងពីក្រោយពួកគេ ដើម្បីកុំឱ្យពួកអ្នកគោរពប្រណិប័តន៍អ្វីក្រៅពីអល់ឡោះ។ (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- ពិតប្រាកដណាស់ ពួកអ្នកចូលរួមជាមួយបុរសៗដោយតណ្ហា លះបង់ស្ត្រីៗទៅវិញ ប៉ុន្តែពួកអ្នកគឺជាជនដែលបំពាន។ (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- ពួកគេស្ថិតនៅជាអមតៈនៅទីនោះ ដរាបណាមេឃ និងផែនដីនៅស្ថិតស្ថេរ លើកលែងតែអ្វីដែលម្ចាស់របស់អ្នកសព្វព្រះហឫទ័យ។ (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- អ្នកដែលនៅលើមេឃ និងអ្នកដែលនៅលើផែនដី លើកលែងតែអ្នកដែលអល់ឡោះសព្វព្រះហឫទ័យ។ (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- នៅទីនោះ ពួកគេនឹងត្រូវបានតុបតែងជាមួយខ្សែក្រវាត់មាស និងគុជខ្យង ហើយពាក់អាវរបស់ពួកគេនៅទីនោះគឺជាសូត្រ។ (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- ហើយទ្រង់បានបញ្ចុះទឹកពីលើមេឃ រួចទ្រង់បណ្តាលឱ្យមានផលិតផលផ្លែឈើជាចំណីអាហារសម្រាប់ពួកអ្នក។ (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
- ហើយនៅពេលដែលយើងបានយកកិច្ចសន្យារបស់ពួកអ្នក ហើយបានលើកភ្នំពីលើពួកអ្នកថាៈ "ចូរពួកអ្នកកាន់យកនូវអ្វីដែលយើងបានផ្តល់ឱ្យពួកអ្នកដោយកម្លាំង។" (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
- បន្ទាប់មក គាត់បានគេចចេញពីពួកគេ ហើយនិយាយថាៈ "ឱក្រុមជនរបស់ខ្ញុំអើយ! ពិតប្រាកដណាស់ ខ្ញុំបានបញ្ជូនសាររបស់ម្ចាស់របស់ខ្ញុំទៅកាន់ពួកអ្នក ហើយបានផ្តល់ឱវាទដល់ពួកអ្នក។" (فَتَوَلَّى عَنْهُمْ وَقَالَ يَاقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّي وَنَصَحْتُ لَكُمْ) 7:79; 7:93
- ទន្លេនានាហូរកាត់ពីក្រោមពួកគេ នៅទីនោះពួកគេនឹងត្រូវបានតុបតែងជាមួយខ្សែក្រវាត់មាស។ (تَجْرِي مِن تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ) 18:31; 22:23
- ប្រសិនបើពួកគេមានអ្វីៗទាំងអស់ដែលនៅលើផែនដី ហើយមានចំនួនស្មើនឹងនោះបន្ថែមទៀត ដើម្បីប្រើវាលោះខ្លួនពួកគេ។ (لَوْ أَنَّ لَهُم مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا) 5:36; 13:18
