- អ្នកដែលប្រតិបត្តិសឡាត បង់ហ្សាកាត និងមានជំនឿយ៉ាងមុតមាំលើថ្ងៃបរលោក។ (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- អ៊ីប្រាហ៊ីម អ៊ីសម៉ាអ៊ីល អ៊ីសហាក យ៉ាកូប និងកូនចៅរបស់ពួកគេ និងអ្វីដែលបានប្រទានដល់មូសា និងអ៊ីសា។ (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- ជាក្រុមៗ រហូតដល់ពេលដែលពួកគេមកដល់វា ទ្វាររបស់វានឹងត្រូវបានបើក ហើយអ្នកយាមរបស់វានឹងនិយាយទៅកាន់ពួកគេ។ (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- អល់ឡោះមិនយកទោសពួកអ្នកដោយសារតែពាក្យឥតប្រយោជន៍ក្នុងការស្បថរបស់ពួកអ្នកទេ ប៉ុន្តែទ្រង់យកទោសពួកអ្នកដោយសារតែ។ (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
