- ឋានសួគ៌នានា ដែលមានទន្លេនានាហូរកាត់ពីក្រោមវា ដោយពួកគេស្ថិតនៅជាអមតៈនៅទីនោះ ហើយអ្វីដែលជាបុណ្យសំណងរបស់អ្នកធ្វើការគឺល្អប្រសើរប៉ុណ្ណា! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- អល់ឡោះជ្រាបនូវអ្វីដែលនៅលើមេឃ និងនៅលើផែនដី ហើយអល់ឡោះ។ (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
