- សម្រាប់ពួកគេ គឺមានបុណ្យសំណងរបស់ពួកគេនៅឯម្ចាស់របស់ពួកគេ ហើយគ្មានការភ័យខ្លាចលើពួកគេទេ ហើយពួកគេ។ (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
