- ចូរពួកអ្នកបរិភោគតាមដែលពួកអ្នកចង់ ប៉ុន្តែកុំចូលទៅជិតដើមឈើនេះឡើយ ដើម្បីកុំឱ្យពួកអ្នកក្លាយជាអ្នកអយុត្តិធម៌។ (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- ចូរអ្នកនិយាយថាៈ "ឱក្រុមជនរបស់ខ្ញុំអើយ! ចូរពួកអ្នកប្រព្រឹត្តតាមលទ្ធភាពរបស់ពួកអ្នក ពិតប្រាកដណាស់ ខ្ញុំក៏ជាអ្នកប្រព្រឹត្តដែរ ហើយពួកអ្នកនឹងដឹង។" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
