- ហើយអ្នកដែលមិនជឿនិយាយថាៈ "ហេតុអ្វីបានជាគេមិនបានបញ្ចុះភស្តុតាងមួយមកលើគាត់ពីម្ចាស់របស់គាត់?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- អ្នកដែលបានបង្កើតពេលយប់សម្រាប់ពួកអ្នក ដើម្បីឱ្យពួកអ្នកសម្រាកនៅក្នុងនោះ និងពេលថ្ងៃ ដើម្បីឱ្យពួកអ្នកមើលឃើញ ពិតប្រាកដណាស់។ (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- មុនពេលដែលថ្ងៃមួយមកដល់ ដែលគ្មានការជួញដូរ និងគ្មានមិត្តភាពឡើយ។ (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- ដើម្បីឱ្យពួកគេពិចារណាថា គ្មានការឆ្កួតអ្វីនៅក្នុងសមមិត្តរបស់ពួកគេទេ គាត់គ្រាន់តែជាអ្នកដាស់តឿនប៉ុណ្ណោះ។ (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- ពួកគេស្ថិតនៅជាអមតៈនៅទីនោះ ទណ្ឌកម្មនឹងមិនត្រូវបានសម្រាលឡើយសម្រាប់ពួកគេ ហើយពួកគេក៏មិនត្រូវបានផ្តល់ពេលវេលាបន្ថែមដែរ។ (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- ចូរកុំបើកភ្នែករបស់អ្នកទៅកាន់អ្វីដែលយើងបានផ្តល់ឱ្យពួកគេមួយចំនួនជាការសប្បាយ។ (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- ហើយកុំបន្ថយឱ្យមនុស្សនូវវត្ថុរបស់ពួកគេ ហើយកុំបង្កចលាចលនៅលើផែនដី។ (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- ហើយសន្តិភាពចូរមានលើគាត់ នៅថ្ងៃដែលគាត់កើត និងថ្ងៃដែលគាត់ស្លាប់ និងថ្ងៃដែលគាត់ត្រូវបានប្រោសឱ្យរស់ឡើងវិញជាមនុស្សរស់។ (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- ឱក្រុមជនរបស់ខ្ញុំអើយ! ចូរពួកអ្នកប្រព្រឹត្តតាមលទ្ធភាពរបស់ពួកអ្នក ពិតប្រាកដណាស់ ខ្ញុំក៏ជាអ្នកប្រព្រឹត្តដែរ ហើយពួកអ្នកនឹងដឹងថាអ្នកណា។ (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- ហើយវាមិនមែនសម្រាប់អ្នកនាំសារណាម្នាក់ក្នុងការនាំយកភស្តុតាងមកឡើយ លើកលែងតែដោយមានការអនុញ្ញាតពីអល់ឡោះ។ (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- បន្ទាប់មក គ្រប់ព្រលឹងនឹងទទួលបាននូវអ្វីដែលខ្លួនបានប្រព្រឹត្តដោយពេញលេញ ហើយពួកគេមិនត្រូវបានគេអយុត្តិធម៌ឡើយ។ (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ទោះជាបុរស ឬស្ត្រី ហើយគាត់ជាអ្នកមានជំនឿ ដូច្នេះពួកគេទាំងនោះនឹងត្រូវបានបញ្ចូលទៅក្នុងឋានសួគ៌។ (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ទ្រង់មិនបានបង្កើតកូនទេ ហើយទ្រង់ក៏គ្មានដៃគូក្នុងការគ្រប់គ្រងដែរ។ (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- ហើយអ្នកណាដែលអល់ឡោះណែនាំ នោះគាត់គឺជាអ្នកទទួលការណែនាំ ហើយអ្នកណាដែលទ្រង់ធ្វើឱ្យវង្វេង នោះអ្នកនឹងមិនដែលរកឃើញ។ (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- ចូរក្រឡេកមើលចុះ តើពួកគេបានប្រដូចយ៉ាងណាចំពោះអ្នក ហើយពួកគេបានវង្វេងហើយ ពួកគេមិនអាចរកផ្លូវបានឡើយ។ (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- ចូរអ្នកនិយាយថាៈ "ពិតប្រាកដណាស់ ខ្ញុំខ្លាចទណ្ឌកម្មនៃថ្ងៃដ៏ធំធេង ប្រសិនបើខ្ញុំមិនស្តាប់បង្គាប់ម្ចាស់របស់ខ្ញុំ។" (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- គ្រឿងអាម៉ាស់របស់ពួកគេទាំងពីរបានលេចចេញឡើង ហើយពួកគេទាំងពីរបានចាប់ផ្តើមយកស្លឹកឈើរបស់ឋានសួគ៌មកបាំងខ្លួនឯង។ (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- ហើយចូរពួកអ្នកអំពាវនាវដល់អ្នកដែលពួកអ្នកអាចអំពាវនាវបាន ក្រៅពីអល់ឡោះ ប្រសិនបើពួកអ្នកជាអ្នកស្មោះត្រង់។ (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- អ្វីៗដែលនៅលើផែនដីទាំងអស់ និងចំនួនស្មើនឹងនោះបន្ថែមទៀត ដើម្បីប្រើវាលោះខ្លួនពួកគេ។ (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- ចូរពួកអ្នកកាន់យកនូវអ្វីដែលយើងបានផ្តល់ឱ្យពួកអ្នកដោយកម្លាំង ហើយចងចាំនូវអ្វីដែលនៅក្នុងនោះ ប្រហែលជាពួកអ្នកនឹងកោតខ្លាច។ (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- តើពួកអ្នកប្រព្រឹត្តអំពើអាសអាភាសដែលគ្មានអ្នកណាម្នាក់ក្នុងចំណោមអ្នកនៅលើលោកិយបានប្រព្រឹត្តពីមុនពួកអ្នកទេឬ? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- ហើយអ្វីៗដែលនៅលើមេឃ និងនៅលើផែនដី គឺជាកម្មសិទ្ធិរបស់អល់ឡោះ ហើយអល់ឡោះគឺជា។ (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- អំពើអាក្រក់ដែលពួកគេបានប្រព្រឹត្ត បានមកដល់ពួកគេ ហើយអ្វីដែលពួកគេធ្លាប់ចំអកឡកឡឺយ បានឡោមព័ទ្ធពួកគេ។ (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- អ្នកនាំសារម្នាក់ពីចំណោមពួកអ្នក ដែលបានសូត្រអាយ៉ាត់ៗរបស់យើងដល់ពួកអ្នក សំអាតពួកអ្នក និងបង្រៀនពួកអ្នកនូវគម្ពីរ និងប្រាជ្ញាវិជ្ជា។ (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- ពីទីនោះ មានប្រភពទឹកចំនួនដប់ពីរ បានហូរចេញមក។ ពិតប្រាកដណាស់ មនុស្សគ្រប់ក្រុមបានដឹងនូវកន្លែងផឹករបស់ខ្លួន។ (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- លើកលែងតែការស្មាន ពិតប្រាកដណាស់ ការស្មានមិនអាចជួយអ្វីបានឡើយចំពោះសេចក្តីពិត។ (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- ហើយនៅពេលដែលខ្ញុំបានបង្កើតគាត់ឱ្យល្អឥតខ្ចោះ ហើយបានផ្លុំវិញ្ញាណរបស់ខ្ញុំចូលទៅក្នុងគាត់ ចូរពួកអ្នកក្រាបចុះចំពោះគាត់។ (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- តើអ្នកណាដែលទទួលបានលទ្ធផលល្អនៅឋាននេះ? ពិតប្រាកដណាស់ អ្នកអយុត្តិធម៌នឹងមិនទទួលបានជោគជ័យឡើយ។ (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- អ្នកដែលបានបង្កើតមេឃ និងផែនដី ទ្រង់ជាអ្នកមានឫទ្ធិអំណាចក្នុងការបង្កើតឱ្យដូចពួកគេ។ (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
