- ពិតប្រាកដណាស់ ម្ចាស់របស់អ្នក ទ្រង់ជ្រាបបំផុតចំពោះអ្នកដែលវង្វេងពីផ្លូវរបស់ទ្រង់។ (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
