- ហើយពិតប្រាកដណាស់ យើងស្ថិតក្នុងការសង្ស័យចំពោះអ្វីដែលអ្នកអំពាវនាវឲ្យយើង។ (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
