- ហើយគ្មានអ្នកនាំសារណាម្នាក់បានមកកាន់ពួកគេទេ លើកលែងតែពួកគេបានចំអកដាក់គាត់។ (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- ពួកគេបាននិយាយថាៈ ឱមូសា! តើអ្នកជាអ្នកបោះ ឬក៏យើងជាអ្នកបោះ? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- ទ្រង់គឺជាអ្នកដែលធ្វើឲ្យពួកអ្នកស្លាប់ ហើយក្នុងចំណោមពួកអ្នក មានអ្នកខ្លះត្រូវបានឲ្យត្រឡប់ទៅកាន់វ័យចាស់ជ្រុល ដើម្បី។ (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
