- ហើយយើងបានដាក់ស្បៃនៅលើដួងចិត្តរបស់ពួកគេ ដើម្បីកុំឲ្យពួកគេយល់វា ហើយថ្លង់នៅត្រចៀករបស់ពួកគេ។ (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
