- នោះគឺដោយសារតែពួកគេបានប្រឆាំងនឹងអល់ឡោះ និងអ្នកនាំសាររបស់ទ្រង់ ហើយអ្នកណាដែលប្រឆាំងនឹងអល់ឡោះ។ (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
