- អ្នកដែលជជែកតវ៉ាអំពីអាយ៉ាត់ៗរបស់អល់ឡោះ ដោយគ្មានអំណាចណាមួយមកដល់ពួកគេ។ (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
