- ហើយនៅពេលដែលយើងបានជួយសង្គ្រោះពួកអ្នកពីពួកហ្វ៊ីរអ៊ូន ដែលពួកគេបានដាក់ទារុណកម្មយ៉ាងធ្ងន់ធ្ងរមកលើពួកអ្នក។ (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
