- តើអ្នកមិនឃើញទេថា អល់ឡោះបានបង្ក្រាបឲ្យពួកអ្នកនូវអ្វីៗដែលនៅក្នុង។ (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- ពួកអ្នកប្រឆាំងនឹងនិយាយថាៈ នេះមិនមែនជាអ្វីក្រៅពីការធ្វើមន្តអាគមដ៏បង្ហាញឲ្យឃើញនោះឡើយ។ (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- ហើយនៅពេលដែលអាយ៉ាត់ៗរបស់យើងត្រូវបានសូត្រដល់ពួកគេយ៉ាងច្បាស់លាស់ ពួកអ្នកប្រឆាំងបាននិយាយថា។ (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- ឋានសួគ៌អាដន់ ដែលមានទន្លេនានាហូរពីក្រោមពួកវា ដោយពួកគេស្ថិតនៅក្នុងនោះជាអមតៈ។ (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
