- ដើម្បីទ្រង់អភ័យទោសឲ្យអំពើបាបរបស់ពួកអ្នក ហើយបង្អង់ពួកអ្នកទៅដល់អាយុកាលដែលបានកំណត់។ (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- តើពួកអ្នកចង់បង្វែរយើងចេញពីអ្វីដែលបុព្វបុរសរបស់យើងធ្លាប់គោរពប្រណិប័តន៍មែនឬ? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- ហើយនៅពេលដែលម្ចាស់របស់អ្នកបានមានបន្ទូលទៅកាន់ពួកម៉ាឡាអ៊ីកាត់ថាៈ ពិតប្រាកដណាស់ ខ្ញុំនឹងបង្កើតមនុស្សពីដីឥដ្ឋ។ (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- ហើយទ្រង់គឺជាអ្នកដែលបញ្ជូនខ្យល់ជាដំណឹងល្អមុននឹងសេចក្ដីមេត្តាករុណារបស់ទ្រង់។ (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- ចូរអ្នកពោលថាៈ ចូរពួកអ្នកធ្វើដំណើរនៅលើផែនដី ហើយមើលថាតើទីបញ្ចប់យ៉ាងណា។ (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- ពិតប្រាកដណាស់ នៅក្នុងការបង្កើតមេឃទាំងឡាយ និងផែនដី និងការផ្លាស់ប្តូរវេននៃពេលយប់ និងពេលថ្ងៃ (គឺជាភស្ដុតាង)។ (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- តើអ្នកណាដែលឲ្យអល់ឡោះខ្ចីកម្ចីដ៏ល្អ ដើម្បីទ្រង់នឹងបង្គុរឲ្យគាត់កាន់តែច្រើន? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- ដូច្នេះ ចូរអ្នកវិនិច្ឆ័យរវាងពួកគេដោយអ្វីដែលអល់ឡោះបានបញ្ចុះ ហើយកុំដើរតាមតណ្ហារបស់ពួកគេ។ (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- តើពួកគេកំពុងរង់ចាំអ្វីក្រៅពីការមកដល់របស់ពួកម៉ាឡាអ៊ីកាត់មកកាន់ពួកគេ ឬការមកដល់នៃបញ្ជារបស់ម្ចាស់អ្នក? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- ពិតប្រាកដណាស់ អ្នកដែលបានប្រឌិតពាក្យកុហកទាស់នឹងអល់ឡោះ ពួកគេមិនទទួលជោគជ័យឡើយ។ (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ដូចរបៀបរបស់ពួកហ្វ៊ីរអ៊ូន និងអ្នកដែលមុនពួកគេ ដែលពួកគេបានប្រឆាំងនឹងអាយ៉ាត់ៗរបស់យើង។ (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- ហើយគាត់ផ្ដល់ដំណឹងល្អដល់អ្នកដែលមានជំនឿ និងប្រព្រឹត្តអំពើល្អថា ពួកគេនឹងទទួលបានរង្វាន់។ (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- អល់ឡោះពង្រីក និងចង្អៀតនូវអាហារូបភោគដល់អ្នកណាដែលទ្រង់សព្វព្រះទ័យក្នុងចំណោមបាវបម្រើរបស់ទ្រង់។ (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- ហើយពួកអ្នកនឹងត្រូវបានប្រមូលត្រឡប់ទៅកាន់អ្នកដែលជ្រាបនូវអាថ៌កំបាំង និងការបង្ហាញ រួចទ្រង់នឹងប្រាប់ពួកអ្នកនូវអ្វីដែលពួកអ្នកធ្លាប់បានប្រព្រឹត្ត។ (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- ហើយសាច់ញាតិជិតស្និទ្ធ ពួកគេខ្លះមានសិទ្ធិជាងអ្នកដទៃក្នុងគម្ពីររបស់អល់ឡោះ។ (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — កាតព្វកិច្ច (ត្រូវតែធ្វើ; ការលះបង់គឺជាអំពើបាប)
- mustahabb / mandub (مستحب / مندوب) — ត្រូវបានណែនាំ (ទទួលបានរង្វាន់ប្រសិនបើធ្វើ មិនមែនជាអំពើបាបទេប្រសិនបើលះបង់)
- mubah (مباح) — អព្យាក្រឹត / អនុញ្ញាត (គ្មានរង្វាន់និងគ្មានបាប)
- makruh (مكروه) — គួរឱ្យស្អប់ខ្ពើម (មិនត្រូវបានគេចូលចិត្ត ប៉ុន្តែមិនមែនជាអំពើបាបទេប្រសិនបើធ្វើ)
- haram (حرام) — ហារាម (ហាមឃាត់; ការធ្វើគឺជាអំពើបាប)
- halal (حلال, អនុញ្ញាត / ស្របច្បាប់) — រួមបញ្ចូលទាំង mubah និង mustahabb — អ្វីៗទាំងអស់ដែលមិនត្រូវបានហាមឃាត់
- ចូរគោរពបូជាតែអល់ឡោះប៉ុណ្ណោះ ហើយសូមជំនួយ/ជំនួយពីទ្រង់។ 1:5
- ចូរគោរពបូជាតែអល់ឡោះប៉ុណ្ណោះ។ 2:21
- កុំធ្វើពហុទេពនិយមជាមួយអល់ឡោះ។ 2:22
- អល់ឡោះគឺជាអ្នកអភ័យទោស (ទទួលយកការប្រែចិត្ត) ទ្រង់បានទទួលយកការប្រែចិត្តរបស់អាដាម (សន្តិភាពកើតមានដល់គាត់)។ 2:37
- កុំលាយបញ្ចូលសេចក្តីពិតជាមួយសេចក្តីមិនពិត ហើយកុំលាក់បាំងសេចក្តីពិត។ 2:42
- ចូរប្រតិបត្តិសឡាត (ការអធិស្ឋានប្រចាំថ្ងៃ) ហើយចូរបង់ហ្សាកាត (ទាន)។ 2:43
- ចូរបង្គាប់អ្នកដទៃឲ្យធ្វើអំពើល្អ លុះត្រាតែអ្នកផ្ទាល់បានអនុវត្តវា។ 2:44
- ចូរស្វែងរកជំនួយពីអល់ឡោះក្នុងកិច្ចការទាំងអស់របស់អ្នក។ 2:45
- កុំចូលរួមក្នុងអំពើពុករលួយ ហើយកុំផ្សព្វផ្សាយវា។ 2:60
- កុំរារាំងមនុស្សពីការទៅកាន់កន្លែងគោរពបូជា។ 2:114
- ចូរគោរពភាពពិសិដ្ឋនៃវិហារអ៊ិស្លាម។ ចូររក្សាកន្លែងអធិស្ឋានរបស់អ្នកឱ្យស្អាតស្អំ និងបរិសុទ្ធ។ 2:125
- ចូរចងចាំអល់ឡោះ (តាមរយៈការអធិស្ឋាន ការសរសើរតម្កើង។ល។) ហើយទ្រង់នឹងចងចាំអ្នក ហើយចូរដឹងគុណចំពោះទ្រង់។ 2:152
- ចូរអត់ធ្មត់ក្នុងគ្រាលំបាក។ 2:153
- កុំដើរតាមគន្លងរបស់ស្ហៃតាន (អារក្ស) ដែលជាសត្រូវច្បាស់លាស់។ 2:168
- កុំដើរតាមនរណាម្នាក់ដោយងងឹតងងុល។ 2:170
- ចូរថែរក្សា និងបំពេញនូវវត្ថុទុកចិត្តទាំងអស់។ ចូរបំពេញកាតព្វកិច្ចសាសនារបស់អ្នកដោយស្មោះត្រង់។ ចូរបំពេញសច្ចាប្រណិធាន និងកិច្ចព្រមព្រៀងរបស់អ្នក។ ចូររក្សាការសន្យា ជាពិសេសការសន្យាដែលបានធ្វើចំពោះអល់ឡោះ។ ចូរគាំទ្រអ្នកដែលត្រូវការ និងបន្ថយការលំបាក។ ចូរចៀសវាងពីការប្រព្រឹត្តអំពើបាបដែលនាំឱ្យបាត់បង់ព្រះគុណដ៏ទេវភាព។ កុំអនុញ្ញាតឱ្យភាពក្រអឺតក្រទមនាំអ្នកឱ្យទៅរកភាពអយុត្តិធម៌។ 2:177
- នៅក្នុងការសងសឹក (ច្បាប់ស្មើភាពក្នុងការផ្តន្ទាទោស) មានជីវិតសម្រាប់អ្នក។ 2:179
- ចូរតមអាហារក្នុងខែរ៉ាម៉ាដាន់។ ចូរប្រតិបត្តិតាមការតមអាហារដែលបានកំណត់ ដើម្បីឱ្យអ្នកក្លាយជាអ្នកកាន់សាសនា (អាល់-មុតតាគីន)។ 2:183
- ចូរគោរពគម្ពីគួរអានជាប្រភពណែនាំចុងក្រោយ។ 2:185
- កុំស៊ីទ្រព្យសម្បត្តិគ្នាទៅវិញទៅមកដោយអយុត្តិធម៌ ហើយកុំផ្តល់សំណូកដល់ចៅក្រម (មុនពេលបង្ហាញករណីរបស់អ្នក)។ 2:188
- កុំជិះជាន់អ្នកដទៃ ទាំងពាក្យសម្តី ឬទង្វើ។ កុំប្រយុទ្ធជាអ្នកឈ្លានពាន ប៉ុន្តែសម្រាប់ការពារខ្លួនតែប៉ុណ្ណោះ។ 2:190
- ចូរការពារក្មេងកំព្រា។ ទាក់ទងនឹងក្មេងកំព្រា ចូរធ្វើការដោយស្មោះត្រង់លើទ្រព្យសម្បត្តិរបស់ពួកគេ ហើយកុំស៊ីទ្រព្យសម្បត្តិរបស់ពួកគេ។ 2:220
- ចូរប្រែចិត្ត ហើយស្វែងរកការអភ័យទោសពីអល់ឡោះ។ កុំរួមភេទអំឡុងពេលមករដូវ។ ចូររក្សាភាពបរិសុទ្ធ (ទាំងផ្លូវកាយ និងផ្លូវចិត្ត)។ 2:222
- ចូរបំពេញការទទួលខុសត្រូវរបស់អ្នកចំពោះគ្រួសាររបស់អ្នក។ 2:233
- ចូរជ្រើសរើសមេដឹកនាំដោយផ្អែកលើគុណសម្បត្តិរបស់ពួកគេ។ 2:247
- មិនមានការបង្ខិតបង្ខំក្នុងសាសនាទេ។ 2:256
- ចូរចំណាយទ្រព្យសម្បត្តិក្នុងការសប្បុរសធម៌។ ចូរមានចិត្តសប្បុរសទាំងទ្រព្យសម្បត្តិ និងពេលវេលា។ 2:261
- កុំធ្វើឱ្យសប្បុរសធម៌របស់អ្នកខូចដោយការអួតពីចិត្តសប្បុរសរបស់អ្នក។ 2:264
- ស្ហៃតាន (អារក្ស) គំរាមកំហែងអ្នកដោយភាពក្រីក្រ ហើយបញ្ជាអ្នកឱ្យប្រព្រឹត្តអំពើថោកទាប (អំពើអាក្រក់ ការរួមភេទខុសច្បាប់ អំពើបាប)។ 2:268
- ចូរស្វែងរកអ្នកដែលត្រូវការ ហើយជួយពួកគេ។ 2:273
- កុំចូលរួមក្នុងការយកការប្រាក់ស៊ី។ កុំស៊ីទ្រព្យសម្បត្តិដែលមានការប្រាក់។ កុំស៊ីរីបា (ការយកការប្រាក់ស៊ី)។ 2:275
- ចូរផ្តល់ពេលវេលាបន្ថែមទៀតដល់កូនបំណុលដើម្បីសងប្រសិនបើគាត់ជួបការលំបាក។ 2:280
- ចូររក្សាពាក្យសម្តីរបស់អ្នកក្នុងប្រតិបត្តិការពាណិជ្ជកម្ម។ ចូរស្មោះត្រង់ក្នុងកិច្ចការហិរញ្ញវត្ថុរបស់អ្នក។ ចូរប្រព្រឹត្តដោយសុចរិតភាពក្នុងការប្តេជ្ញាចិត្តទាំងអស់របស់អ្នក។ នៅពេលអ្នកចុះកិច្ចសន្យាបំណុលសម្រាប់រយៈពេលកំណត់ ចូរសរសេរវា។ ចូរយកសាក្សីរាល់ពេលដែលអ្នកចុះកិច្ចសន្យាពាណិជ្ជកម្ម។ 2:282
- ចូរថែរក្សា និងបំពេញនូវវត្ថុទុកចិត្តទាំងអស់។ 2:283
- ចូរជឿលើគម្ពីរដែលបានបញ្ចុះ និងព្យាការីទាំងអស់។ 2:285
- អល់ឡោះមិនដាក់បន្ទុកលើនរណាម្នាក់ឱ្យលើសពីសមត្ថភាពរបស់គាត់ឡើយ។ គាត់នឹងទទួលបានរង្វាន់ចំពោះអំពើល្អដែលគាត់បានប្រព្រឹត្ត និងទទួលទោសចំពោះអំពើអាក្រក់ដែលគាត់បានប្រព្រឹត្ត។ ព្រះមិនដាក់បន្ទុកលើមនុស្សឱ្យលើសពីសមត្ថភាពរបស់គាត់ទេ។ យើងក៏មិនគួរធ្វើដូច្នោះដែរ។ ចូរជឿទុកចិត្តលើផែនការរបស់អល់ឡោះ សូម្បីតែក្នុងគ្រាលំបាកក៏ដោយ។ 2:286
- អ្នកណាដែលបំពេញកិច្ចព្រមព្រៀង និងកោតខ្លាចអល់ឡោះ នោះអល់ឡោះស្រឡាញ់អ្នកដែលកោតខ្លាចព្រះ។ 3:76
- ចូរធ្វើហាជ (ធម្មយាត្រា) ប្រសិនបើអ្នកអាចធ្វើបាន។ 3:97
- កុំបែកគ្នា។ 3:103
- ចូរបង្គាប់ឱ្យធ្វើអំពើល្អ និងហាមឃាត់អំពើអាក្រក់។ ចូរលើកទឹកចិត្តដល់សុចរិតភាពក្នុងសហគមន៍របស់អ្នក។ ចូរអំពាវនាវអ្នកដទៃឱ្យចងចាំអល់ឡោះ។ 3:104
- អ្នកជឿគួរតែដាក់ទំនុកចិត្តលើអល់ឡោះ។ 3:122
- កុំស៊ីរីបា (ការយកការប្រាក់ស៊ី)។ 3:130
- ចូរគោរពតាមអល់ឡោះ និងអ្នកនាំសាររបស់ទ្រង់ ដើម្បីទទួលបានសេចក្តីមេត្តាករុណា។ 3:132
- អល់ឡោះស្រឡាញ់អ្នកដែលចំណាយ (ក្នុងមាគ៌ារបស់អល់ឡោះ — អំពើសប្បុរសធម៌ ទាន។ល។) ទាំងក្នុងគ្រាសម្បូរណ៍ និងទុក្ខលំបាក អ្នកដែលទប់ចិត្តកំហឹង និងអ្នកដែលអភ័យទោសដល់មនុស្ស។ 3:134
- ចូរទប់ចិត្តកំហឹង។ ចូរគ្រប់គ្រងកំហឹងរបស់អ្នក។ 3:134
- ចូរអភ័យទោស និងលើកលែងទោសដល់កំហុសរបស់អ្នកដទៃ។ 3:135
- កុំពោលពាក្យគ្រើមគ្រើន។ ចូរអត់ធ្មត់ចំពោះអ្នកដែលមានគំនិតខុសពីអ្នក។ 3:159
- ប្រសិនបើអល់ឡោះជួយអ្នក គ្មាននរណាម្នាក់អាចយកឈ្នះអ្នកបានឡើយ។ ហើយប្រសិនបើទ្រង់បោះបង់ចោលអ្នក តើអ្នកណាក្រៅពីទ្រង់អាចជួយអ្នកបាន? 3:160
- គ្រប់ៗគ្នានឹងទទួលរសជាតិនៃសេចក្តីស្លាប់។ ហើយមានតែនៅថ្ងៃបរលោកប៉ុណ្ណោះ ទើបអ្នកទទួលបានរង្វាន់ពេញលេញរបស់អ្នក។ 3:185
- ចូរគិតពិចារណាយ៉ាងជ្រៅអំពីអច្ឆរិយៈនៃធម្មជាតិ និងការបង្កើតសកលលោកនេះ។ ចូរដឹងថាព្រះបានបង្កើតសកលលោកដោយអត្ថន័យ និងគោលបំណង។ 3:191
- បុរសនិងស្ត្រីទទួលបានរង្វាន់ស្មើគ្នាចំពោះអំពើរបស់ពួកគេ។ 3:195
- សម្រាប់អ្នកដែលកោតខ្លាចព្រះជាម្ចាស់របស់ពួកគេ គឺមានសួនច្បារ (នៅស្ថានសួគ៌) ដែលមានទន្លេហូរកាត់ក្រោមពួកវា។ ពួកគេនឹងស្ថិតនៅទីនោះជារៀងរហូត ជាទានពីអល់ឡោះ។ 3:198
- ចូរខិតខំជានិច្ចដើម្បីសេចក្តីពេញចិត្តរបស់អល់ឡោះក្នុងគ្រប់សកម្មភាព។ 3:200
- ចូរកោតខ្លាចព្រះជាម្ចាស់របស់អ្នក ហើយ (កុំកាត់ផ្តាច់) ចំណងញាតិសន្តាន។ 4:1
- ចូរប្រគល់ទ្រព្យសម្បត្តិដល់ក្មេងកំព្រា ហើយកុំផ្លាស់ប្តូរ (របស់អាក្រក់របស់អ្នក) ជាមួយ (របស់ល្អរបស់ពួកគេ)។ ហើយកុំស៊ីទ្រព្យសម្បត្តិរបស់ពួកគេ (ដោយបញ្ចូលវាទៅក្នុងទ្រព្យសម្បត្តិរបស់អ្នក)។ 4:2
- ចូរប្រគល់ម៉ាហរ (ថ្លៃបណ្ណាការជាកាតព្វកិច្ចដែលប្តីផ្តល់ឱ្យប្រពន្ធនៅពេលរៀបការ) ដល់ស្ត្រី (ដែលអ្នករៀបការ) ដោយចិត្តសប្បុរស។ 4:4
- ចូរការពារសិទ្ធិរបស់ក្មេងកំព្រា។ 4:6
- ទ្រព្យសម្បត្តិរបស់អ្នកស្លាប់គួរតែត្រូវបានចែកចាយក្នុងចំណោមសមាជិកគ្រួសាររបស់គាត់។ ស្ត្រីមានសិទ្ធិទទួលមរតក។ 4:7
- កុំស៊ីទ្រព្យសម្បត្តិរបស់ក្មេងកំព្រាដោយអយុត្តិធម៌។ 4:10
- ចូរគោរពតាមបញ្ជាទាក់ទងនឹងមរតក។ 4:11
- វាត្រូវបានហាមឃាត់មិនឱ្យទទួលមរតកពីស្ត្រីដោយប្រឆាំងនឹងឆន្ទៈរបស់ពួកគេ ហើយអ្នកមិនគួរប្រព្រឹត្តចំពោះពួកគេយ៉ាងឃោរឃៅឡើយ។ ចូររស់នៅជាមួយពួកគេ (ប្រពន្ធ) ដោយកិត្តិយស។ ចូរគោរព និងថែរក្សាសិទ្ធិរបស់ស្ត្រី។ ចូរប្រព្រឹត្តចំពោះដៃគូរបស់អ្នកដោយសេចក្តីសប្បុរស និងមេត្តាករុណា។ ចូរប្រព្រឹត្តចំពោះស្ត្រីដោយកិត្តិយស និងយុត្តិធម៌។ 4:19
- កុំរៀបការជាមួយអ្នកដែលមានឈាមសាច់ជាមួយអ្នក។ 4:23
- កុំសម្លាប់ខ្លួនឯង (ឬសម្លាប់គ្នាទៅវិញទៅមក)។ ពិតប្រាកដណាស់ អល់ឡោះមានមេត្តាករុណាចំពោះអ្នក។ កុំស៊ីទ្រព្យសម្បត្តិគ្នាទៅវិញទៅមកដោយអយុត្តិធម៌។ 4:29
- ប្រសិនបើអ្នកចៀសវាងអំពើបាបធំៗដែលត្រូវបានហាមឃាត់ អល់ឡោះនឹងលើកលែងទោសឱ្យអ្នកនូវអំពើបាប (តូចតាច) របស់អ្នក ហើយនឹងបញ្ចូលអ្នកទៅក្នុងច្រកចូលដ៏ថ្លៃថ្នូរ (ស្ថានសួគ៌)។ 4:31
- កុំប្រាថ្នាចង់បានអ្វីដែលអល់ឡោះបានផ្តល់ឱ្យអ្នកខ្លះប្រសើរជាងអ្នកដទៃ។ ចូរចៀសវាងការច្រណែន និងការប្រច័ណ្ឌ។ 4:32
- បុរសគឺជាអ្នកការពារ និងថែរក្សាស្ត្រី ដោយសារតែអល់ឡោះបានផ្តល់ឱ្យពួកគេខ្លះប្រសើរជាងអ្នកដទៃ និងដោយសារតែពួកគេចំណាយ (ដើម្បីចិញ្ចឹមពួកគេ) ពីទ្រព្យសម្បត្តិរបស់ពួកគេ។ បុរសគឺជាអ្នកការពារ និងជាអ្នកគាំទ្រគ្រួសារ។ 4:34
- ចូរគោរពបូជាអល់ឡោះ ហើយកុំធ្វើពហុទេពនិយមជាមួយទ្រង់ ចូរធ្វើល្អចំពោះឪពុកម្តាយ ញាតិមិត្ត ក្មេងកំព្រា អ្នកក្រ អ្នកជិតខាង ដៃគូនៅក្បែរអ្នក អ្នកដំណើរ (ដែលអ្នកជួប) និងអ្នកដែល (ទាសករ) ដែលដៃស្តាំរបស់អ្នកកាន់កាប់។ អល់ឡោះមិនស្រឡាញ់អ្នកដែលក្រអឺតក្រទម និងអួតអាងឡើយ។ ចូរធ្វើល្អចំពោះអ្នកដទៃ។ ចូរមេត្តាចំពោះអ្នកទន់ខ្សោយ។ ចូររក្សាចំណងគ្រួសារ និងគោរពញាតិមិត្ត។ 4:36
- កុំកំណាញ់។ 4:37
- អល់ឡោះមិនអភ័យទោសឱ្យការធ្វើពហុទេពនិយមជាមួយទ្រង់ទេ ប៉ុន្តែទ្រង់អភ័យទោសឱ្យអ្វីផ្សេងក្រៅពីនោះចំពោះអ្នកណាដែលទ្រង់សព្វព្រះទ័យ។ 4:48
- កុំច្រណែននឹងអ្នកដទៃ។ 4:54
- អល់ឡោះបញ្ជាអ្នកឱ្យប្រគល់វត្ថុទុកចិត្តទៅឱ្យម្ចាស់របស់វា។ នៅពេលអ្នកវិនិច្ឆ័យរវាងមនុស្ស ចូរវិនិច្ឆ័យដោយយុត្តិធម៌។ 4:58
- ចូរគោរពតាមអល់ឡោះ និងអ្នកនាំសាររបស់ទ្រង់។ ចូរគោរពអ្នកដែលមានអំណាចក្នុងចំណោមអ្នក។ 4:59
- កុំជិះជាន់អ្នកទន់ខ្សោយ និងងាយរងគ្រោះ។ 4:75
- អ្វីដែលល្អដែលកើតមានចំពោះអ្នក គឺមកពីអល់ឡោះ។ ហើយអ្វីដែលអាក្រក់ដែលកើតមានចំពោះអ្នក គឺមកពីខ្លួនអ្នកផ្ទាល់។ 4:79
- អ្នកណាដែលគោរពតាមអ្នកនាំសារ (មូហាំម៉ាត់ ﷺ) នោះគាត់បានគោរពតាមអល់ឡោះ។ 4:80
- អ្នកណាដែលអង្វរករដើម្បីអំពើល្អ គាត់នឹងទទួលបានចំណែកនៃរង្វាន់របស់វា។ ហើយអ្នកណាដែលអង្វរករដើម្បីអំពើអាក្រក់ គាត់នឹងទទួលបានចំណែកនៃបន្ទុករបស់វា។ 4:85
- អ្នកជឿមិនគួរសម្លាប់អ្នកជឿឡើយ លើកលែងតែដោយចៃដន្យ។ 4:92
- អ្នកណាដែលសម្លាប់អ្នកជឿដោយចេតនា ការផ្តន្ទាទោសរបស់គាត់គឺនរក ដែលគាត់នឹងស្ថិតនៅក្នុងនោះជារៀងរហូត។ ព្រះពិរោធ និងបណ្តាសារបស់អល់ឡោះគឺនៅលើគាត់ ហើយការផ្តន្ទាទោសដ៏ធំធេងត្រូវបានរៀបចំសម្រាប់គាត់។ 4:93
- អ្នកណាដែលធ្វើចំណាកស្រុក (ពីផ្ទះរបស់គាត់) ក្នុងមាគ៌ារបស់អល់ឡោះ គាត់នឹងរកឃើញនៅលើផែនដីនូវទីជម្រកជាច្រើន និងភាពបរិបូរណ៍។ 4:100
- ចូរប្រតិបត្តិការអធិស្ឋានរបស់អ្នកឱ្យទាន់ពេលវេលា។ 4:103
- កុំគាំទ្រ ឬធ្វើជាមេធាវីឱ្យអ្នកដែលក្បត់វត្ថុទុកចិត្តរបស់ពួកគេ។ 4:105
- ចូរស្វែងរកការអភ័យទោសពីអល់ឡោះ ពិតប្រាកដណាស់អល់ឡោះគឺជាអ្នកអភ័យទោស មេត្តាករុណា។ 4:106
- ឱអ្នកដែលមានជំនឿ! ចូរតាំងខ្លួនយ៉ាងមុតមាំក្នុងយុត្តិធម៌ ធ្វើជាសាក្សីសម្រាប់អល់ឡោះ បើទោះជាប្រឆាំងនឹងខ្លួនអ្នក ឬឪពុកម្តាយរបស់អ្នក ឬញាតិមិត្តរបស់អ្នកក៏ដោយ ទោះគាត់ជាអ្នកមាន ឬអ្នកក្រក៏ដោយ។ កុំបង្អង់យុត្តិធម៌។ ចូរធ្វើសកម្មភាពភ្លាមៗដើម្បីកែតម្រូវកំហុស។ 4:135
- ពួកពុតត្បុតព្យាយាមបញ្ឆោតអល់ឡោះ ប៉ុន្តែទ្រង់ជាអ្នកបញ្ឆោតពួកគេ។ 4:142
- ពួកពុតត្បុតនឹងស្ថិតនៅក្នុងថ្នាក់ទាបបំផុតនៃភ្លើងនរក។ ហើយអ្នកនឹងមិនអាចរកឃើញអ្នកជួយណាមួយសម្រាប់ពួកគេឡើយ។ 4:145
- អល់ឡោះមិនចូលចិត្តឱ្យគេនិយាយអំពើអាក្រក់ជាសាធារណៈទេ លើកលែងតែអ្នកដែលត្រូវគេជិះជាន់ប៉ុណ្ណោះ។ 4:148
- ពួកអ្នកនាំសារជាអ្នកនាំព័ត៌មានល្អ និងជាអ្នកព្រមាន ដើម្បីកុំឱ្យមនុស្សមានលេសប្រឆាំងនឹងអល់ឡោះ បន្ទាប់ពីពួកអ្នកនាំសារ (បានមក)។ 4:165
- ចូរបំពេញកិច្ចសន្យា និងការសន្យារបស់អ្នក។ 5:1
- ចូរជួយគ្នាទៅវិញទៅមកក្នុងការធ្វើអំពើល្អ និងការកោតខ្លាចព្រះ ហើយកុំជួយគ្នាក្នុងអំពើបាប និងអរិភាព។ 5:2
- កុំស៊ីសាច់សត្វងាប់ ឈាម និងសាច់ជ្រូក។ 5:3
- ចូរប្រព្រឹត្តដោយយុត្តិធម៌ កុំអនុញ្ញាតឱ្យអរិភាព និងការស្អប់ខ្ពើមចំពោះអ្នកដទៃនាំឱ្យអ្នកឃ្លាតឆ្ងាយពីយុត្តិធម៌។ ចូរប្រព្រឹត្តដោយយុត្តិធម៌។ ចូរដឹងថាការប្រព្រឹត្តដោយយុត្តិធម៌គឺជិតស្និទ្ធនឹងការកោតខ្លាចព្រះ។ កុំបង្អង់យុត្តិធម៌។ ចូរធ្វើសកម្មភាពភ្លាមៗដើម្បីកែតម្រូវកំហុស។ 5:8
- ចូរស្វែងរកមធ្យោបាយដើម្បីចូលទៅជិតអល់ឡោះ ហើយចូរតស៊ូក្នុងមាគ៌ារបស់ទ្រង់ឱ្យអស់ពីសមត្ថភាព។ ដើម្បីឱ្យអ្នកទទួលបានជោគជ័យ។ 5:35
- ចូរបំពេញសច្ចាប្រណិធាន និងកិច្ចព្រមព្រៀងរបស់អ្នក។ 5:89
- ចូរចៀសវាងគ្រឿងស្រវឹង និងអាល់កុល។ ចូរចៀសវាងយ៉ាងតឹងរ៉ឹងនូវគ្រឿងស្រវឹង (ភេសជ្ជៈមានជាតិអាល់កុលគ្រប់ប្រភេទ) ការលេងល្បែងស៊ីសង អាល់-អាន់សាប (អាសនៈថ្ម) និងអាល់-អាហ្សឡាម (ព្រួញសម្រាប់ស្វែងរកសំណាង ឬការសម្រេចចិត្ត) ដែលសុទ្ធតែជាភាពស្មោកគ្រោកនៃកិច្ចការរបស់ស្ហៃតាន។ 5:90
- កុំបរបាញ់សត្វព្រៃ ខណៈពេលដែលអ្នកស្ថិតក្នុងស្ថានភាពអ៊ីហ្រាមសម្រាប់ហាជ ឬអ៊ុមរ៉ា (ធម្មយាត្រា)។ 5:95
- កុំសួរអំពីរឿងដែលប្រសិនបើត្រូវបានបញ្ជាក់ឱ្យអ្នកដឹងអាចធ្វើឱ្យអ្នកពិបាកចិត្ត។ 5:101
- កុំប្រមាថអាទិទេពរបស់អ្នកដទៃ។ កុំប្រមាថអ្វីដែលពួកគេ (អ្នកមិនជឿ) គោរពបូជាក្រៅពីអល់ឡោះ បើមិនដូច្នេះទេពួកគេនឹងប្រមាថអល់ឡោះដោយភាពល្ងង់ខ្លៅ។ 6:108
- ប្រសិនបើអ្នកគោរពតាមភាគច្រើននៃអ្នកដែលនៅលើផែនដី ពួកគេនឹងធ្វើឱ្យអ្នកវង្វេងពីមាគ៌ារបស់អល់ឡោះ។ ពួកគេដើរតាមតែការស្មាន ហើយពួកគេគ្រាន់តែកុហកប៉ុណ្ណោះ។ 6:116
- ចូរលះបង់ (ឱមនុស្ស) អំពើបាបគ្រប់ប្រភេទ ទាំងបើកចំហ និងសម្ងាត់។ 6:120
- ចូរកុំបរិភោគ (ឱអ្នកជឿ) ពី (សាច់) ដែលព្រះនាមរបស់អល់ឡោះមិនត្រូវបានគេអំពាវនាវ (នៅពេលសម្លាប់សត្វ)។ 6:121
- អ្នកណាដែលអល់ឡោះចង់ចង្អុលបង្ហាញ ទ្រង់នឹងបើកចិត្តទ្រូងរបស់គាត់សម្រាប់ឥស្លាម។ ហើយអ្នកណាដែលទ្រង់ចង់ធ្វើឱ្យវង្វេង ទ្រង់នឹងធ្វើឱ្យចិត្តទ្រូងរបស់គាត់ចង្អៀត និងតឹងតែង។ 6:125
- ចូរមានភាពល្មមក្នុងការចំណាយ និងចៀសវាងការខ្ជះខ្ជាយ។ ចូរការពារសិទ្ធិរបស់សត្វលោកទាំងអស់។ 6:141
- កុំធ្វើពហុទេពនិយមជាមួយអល់ឡោះ ចូរធ្វើល្អចំពោះឪពុកម្តាយ កុំសម្លាប់កូនរបស់អ្នកដោយសារតែការភ័យខ្លាចភាពក្រីក្រ កុំចូលទៅជិតអំពើថោកទាប កុំសម្លាប់ជីវិតដែលអល់ឡោះបានហាមឃាត់ លើកលែងតែមានហេតុផលត្រឹមត្រូវ។ 6:151
- ចូរស្មោះត្រង់។ កុំបន្លំបំភាន់ក្នុងប្រតិបត្តិការណាមួយរបស់អ្នក។ កុំចូលទៅជិតទ្រព្យសម្បត្តិរបស់ក្មេងកំព្រា លើកលែងតែដើម្បីកែលម្អវា ចូរប្រគល់រង្វាស់ និងទម្ងន់ពេញលេញដោយយុត្តិធម៌ នៅពេលអ្នកនិយាយ ចូរនិយាយការពិត សូម្បីតែប្រឆាំងនឹងសាច់ញាតិក៏ដោយ ហើយចូរបំពេញកិច្ចព្រមព្រៀងរបស់អល់ឡោះ។ 6:152
- ចូរដើរតាមមាគ៌ាត្រង់ ហើយកុំដើរតាមមាគ៌ា (ផ្សេងទៀត) ពីព្រោះវានឹងធ្វើឱ្យអ្នកបែកចេញពីមាគ៌ារបស់ទ្រង់។ 6:153
- ចូរនិយាយ (ឱមូហាំម៉ាត់ ﷺ) ថា: "ពិតប្រាកដណាស់ ការអធិស្ឋានរបស់ខ្ញុំ ការថ្វាយបង្គំរបស់ខ្ញុំ ជីវិតរបស់ខ្ញុំ និងការស្លាប់របស់ខ្ញុំ គឺសម្រាប់អល់ឡោះ ដែលជាម្ចាស់នៃសកលលោកទាំងឡាយ។" 6:162
- កុំក្រអឺតក្រទម។ 7:13
- កុំអនុញ្ញាតឱ្យស្ហៃតានបញ្ឆោតអ្នក។ 7:27
- ចូរនិយាយ (ឱមូហាំម៉ាត់ ﷺ) ថា: "ព្រះជាម្ចាស់របស់ខ្ញុំបានបញ្ជាឱ្យមានយុត្តិធម៌…" 7:29
- ចូរប្រកាន់ខ្ជាប់នូវព្រំដែនដែលអល់ឡោះបានកំណត់ក្នុងគ្រប់កិច្ចការ។ ចូរចៀសវាងការរំលងព្រំដែនក្នុងការនិយាយ និងសកម្មភាព។ ចូរបរិភោគ និងផឹក ប៉ុន្តែកុំធ្វើហួសហេតុពេក។ ចូរស្លៀកពាក់ស្អាតក្នុងពេលអធិស្ឋាន។ 7:31
- អល់ឡោះបានបង្កើតផ្ទៃមេឃ និងផែនដីក្នុងរយៈពេលប្រាំមួយថ្ងៃ រួចទ្រង់គង់លើអាសនៈ (តាមរបៀបដែលសមស្របនឹងភាពអស្ចារ្យរបស់ទ្រង់)។ 7:54
- ចូរអធិស្ឋានទៅកាន់ព្រះជាម្ចាស់របស់អ្នកដោយចិត្តរាបទាប និងសម្ងាត់។ ទ្រង់មិនស្រឡាញ់អ្នកដែលរំលងព្រំដែនឡើយ។ 7:55
- ហើយកុំបង្កអំពើវិនាសនៅលើផែនដី បន្ទាប់ពីវាត្រូវបានគេកែលម្អ ហើយចូរអធិស្ឋានទៅកាន់ទ្រង់ដោយការភ័យខ្លាច និងសង្ឃឹម។ 7:56
- ប៉ុន្តែអ្នកដែលបានប្រព្រឹត្តអំពើអាក្រក់ ហើយប្រែចិត្តបន្ទាប់ពីនោះ ហើយបានជឿ នោះពិតប្រាកដណាស់ ព្រះជាម្ចាស់របស់អ្នក បន្ទាប់ពីនោះ គឺជាអ្នកអភ័យទោស មេត្តាករុណា។ 7:153
- ចូរនិយាយ (ឱមូហាំម៉ាត់ ﷺ) ថា: "ឱមនុស្ស! ពិតប្រាកដណាស់ ខ្ញុំគឺជាអ្នកនាំសាររបស់អល់ឡោះមកកាន់អ្នកទាំងអស់គ្នា…" 7:158
- ហើយព្រះនាមដ៏ស្រស់ស្អាតបំផុតទាំងអស់គឺសម្រាប់អល់ឡោះ ដូច្នេះចូរអំពាវនាវដល់ទ្រង់តាមរយៈព្រះនាមទាំងនោះ ហើយចូរចាកចេញពីអ្នកដែលបំភ្លៃព្រះនាមរបស់ទ្រង់… 7:180
- អ្នកណាដែលអល់ឡោះធ្វើឱ្យវង្វេង នោះគ្មានអ្នកណែនាំណាម្នាក់សម្រាប់គាត់ឡើយ។ ហើយទ្រង់ទុកឱ្យពួកគេវង្វេងដោយងងឹតងងុលក្នុងការរំលងព្រំដែនរបស់ពួកគេ។ 7:186
- ចូរអភ័យទោស ចូរបង្គាប់ឱ្យធ្វើអំពើល្អ ហើយចូរងាកចេញពីអ្នកល្ងង់ខ្លៅ (ឧ. កុំដាក់ទោសពួកគេ)។ 7:199
- ចូរអភ័យទោសដល់អ្នកដទៃចំពោះកំហុសរបស់ពួកគេ។ 7:199
- ហើយប្រសិនបើការញុះញង់អាក្រក់ពីស្ហៃតានមកដល់អ្នក ចូរស្វែងរកទីពឹងជ្រកក្នុងអល់ឡោះ។ ពិតប្រាកដណាស់ ទ្រង់គឺជាអ្នកស្តាប់ អ្នកដឹង។ 7:200
- អ្នកជឿគឺជាអ្នកដែលនៅពេលដែលអល់ឡោះត្រូវបានគេចងចាំ ចិត្តរបស់ពួកគេភ័យខ្លាច ហើយនៅពេលដែលខគម្ពីររបស់ទ្រង់ត្រូវបានគេសូតឱ្យពួកគេស្តាប់ វាបង្កើនជំនឿរបស់ពួកគេ… 8:2
- កុំក្បត់អល់ឡោះ និងអ្នកនាំសាររបស់ទ្រង់ ហើយកុំក្បត់វត្ថុទុកចិត្តរបស់អ្នក (និងកាតព្វកិច្ចទាំងអស់ដែលអល់ឡោះបានបញ្ជាឱ្យអ្នក) ដោយដឹងខ្លួន។ 8:27
- ប្រសិនបើអ្នកកោតខ្លាច និងគោរពតាមអល់ឡោះ ទ្រង់នឹងផ្តល់ឱ្យអ្នកនូវហ្វួហ្កាន (លក្ខណៈវិនិច្ឆ័យដើម្បីបែងចែករវាងការពិត និងការភូតកុហក ឬផ្លូវចេញពីរាល់ការលំបាក)។ 8:29
- អ្នកដែលមិនជឿចំណាយទ្រព្យសម្បត្តិរបស់ពួកគេដើម្បីរារាំង (មនុស្ស) ពីមាគ៌ារបស់អល់ឡោះ ហើយពួកគេនឹងបន្តចំណាយវា។ ប៉ុន្តែនៅទីបញ្ចប់ វានឹងក្លាយជាទុក្ខសោកសម្រាប់ពួកគេ។ 8:36
- ចូរនិយាយទៅកាន់អ្នកដែលមិនជឿថា ប្រសិនបើពួកគេឈប់ (ពីការមិនជឿ) អំពើបាបពីមុនរបស់ពួកគេនឹងត្រូវបានអភ័យទោស។ ប៉ុន្តែប្រសិនបើពួកគេត្រឡប់ទៅវិញ នោះគំរូរបស់អ្នក (ដែលត្រូវបានផ្តន្ទាទោស) មុនពួកគេបានកន្លងផុតទៅហើយ (ជាការព្រមាន)។ 8:38
- នៅពេលអ្នកប្រឈមមុខនឹងកម្លាំង (សត្រូវ) ចូរតាំងខ្លួនឱ្យមាំមួន ហើយចូរចងចាំព្រះនាមអល់ឡោះឱ្យបានច្រើន (ទាំងអណ្តាត និងគំនិត) ដើម្បីឱ្យអ្នកទទួលបានជោគជ័យ។ 8:45
- កុំដូចអ្នកដែលចេញពីផ្ទះរបស់ពួកគេដោយក្រអឺតក្រទម និងដើម្បីឱ្យមនុស្សឃើញ ហើយ (រារាំងមនុស្ស) ពីមាគ៌ារបស់អល់ឡោះ។ 8:47
- អល់ឡោះនឹងមិនផ្លាស់ប្តូរព្រះគុណដែលទ្រង់បានប្រទានដល់មនុស្សជាតិមួយក្រុមទេ លុះត្រាតែពួកគេផ្លាស់ប្តូរអ្វីដែលមាននៅក្នុងខ្លួនពួកគេ។ 8:53
- សត្វដែលអាក្រក់បំផុតនៅចំពោះមុខអល់ឡោះគឺអ្នកដែលមិនជឿ។ 8:55
- ព្រះដាក់សេចក្តីស្រឡាញ់ និងការស្រលាញ់រវាងចិត្តរបស់អ្នកដែលជឿលើទ្រង់។ 8:63
- ចូរការពារ និងជួយអ្នកដែលស្វែងរកការការពារ។ 9:6
- មិនសមរម្យសម្រាប់ពួកពហុទេពនិយមក្នុងការថែរក្សាវិហារអ៊ិស្លាមរបស់អល់ឡោះទេ។ 9:17
- ពួកគេ (អ្នកមិនជឿ ជនជាតិយូដា និងគ្រិស្តសាសនិក) ចង់ពន្លត់ពន្លឺរបស់អល់ឡោះ (ដែលមូហាំម៉ាត់ ﷺ ត្រូវបានគេបញ្ជូនមកជាមួយ — ជំនឿលើព្រះតែមួយរបស់ឥស្លាម) ដោយមាត់របស់ពួកគេ ប៉ុន្តែអល់ឡោះនឹងមិនអនុញ្ញាតឱ្យមានអ្វីក្រៅពីការបំពេញពន្លឺរបស់ទ្រង់ឡើយ ទោះបីជាអ្នកមិនជឿស្អប់វាក៏ដោយ។ 9:32
- ការបរិច្ចាគ (ហ្សាកាត) គឺសម្រាប់តែ៖ ១) អ្នកក្រ (ហ្វុការ៉ា) ២) អ្នកខ្វះខាត (អាល់-ម៉ាសាគីន) ៣) អ្នកដែលត្រូវបានចាត់តាំងឱ្យប្រមូលវា ៤) ដើម្បីទាក់ទាញចិត្តរបស់អ្នកដែលមានទំនោរទៅរកឥស្លាម ៥) ដើម្បីរំដោះទាសករ ៦) សម្រាប់អ្នកដែលមានបំណុល ៧) សម្រាប់មាគ៌ារបស់អល់ឡោះ (សម្រាប់អ្នកតស៊ូ) និង ៨) សម្រាប់អ្នកដំណើរ។ 9:60
- អ្នកណាដែលប្រឆាំង និងបង្ហាញអរិភាពចំពោះអល់ឡោះ និងអ្នកនាំសាររបស់ទ្រង់ (ﷺ) ពិតប្រាកដណាស់ សម្រាប់គាត់គឺជាភ្លើងនរក ដែលគាត់នឹងស្ថិតនៅក្នុងនោះជារៀងរហូត។ នោះគឺជាការអាម៉ាស់ដ៏ធំធេង។ 9:63
- ពួកពុតត្បុត បុរស និងស្ត្រី គឺមកពីគ្នាទៅវិញទៅមក។ ពួកគេបានភ្លេចអល់ឡោះ ដូច្នេះទ្រង់ក៏ភ្លេចពួកគេ។ 9:67
- ចូរខិតខំដើម្បីភាពបរិសុទ្ធ។ ចូរគោរពភាពពិសិដ្ឋនៃវិហារអ៊ិស្លាម។ 9:108
- មិនសមរម្យសម្រាប់ (ព្យាការី និងអ្នកជឿ) ក្នុងការស្វែងរកការអភ័យទោសពីអល់ឡោះសម្រាប់ពួកពហុទេពនិយម ទោះបីជាពួកគេជាសាច់ញាតិក៏ដោយ បន្ទាប់ពីវាច្បាស់ចំពោះពួកគេថាពួកគេជាអ្នកនៅនរក (ដោយសារតែពួកគេបានស្លាប់ក្នុងស្ថានភាពមិនជឿ)។ 9:113
- តើអ្នកណាដែលអយុត្តិធម៌ជាងអ្នកដែលបង្កើតការកុហកប្រឆាំងនឹងអល់ឡោះ ឬបដិសេធខគម្ពីររបស់ទ្រង់? ពិតប្រាកដណាស់ ពួកឧក្រិដ្ឋជននឹងមិនទទួលបានជោគជ័យឡើយ! 10:17
- ពួកគេគោរពបូជាក្រៅពីអល់ឡោះនូវអ្វីដែលមិនអាចបង្កគ្រោះថ្នាក់ ឬផ្តល់ប្រយោជន៍ដល់ពួកគេ ហើយពួកគេនិយាយថា: "ទាំងនេះគឺជាអ្នកអង្វរកររបស់យើងនៅឯអល់ឡោះ។" ចូរនិយាយថា: "តើអ្នកប្រាប់អល់ឡោះពីអ្វីដែលទ្រង់មិនដឹងនៅលើមេឃ និងនៅលើផែនដីឬ?" សូមលើកតម្កើងទ្រង់ ហើយទ្រង់ខ្ពង់ខ្ពស់ជាងអ្វីដែលពួកគេធ្វើពហុទេពនិយមជាមួយទ្រង់! 10:18
- ការផ្តន្ទាទោសចំពោះអំពើអាក្រក់គឺអំពើអាក្រក់ដូចគ្នា។ 10:27
- នោះគឺអល់ឡោះ ដែលជាព្រះជាម្ចាស់ពិតប្រាកដរបស់អ្នក។ ដូច្នេះបន្ទាប់ពីការពិត តើមានអ្វីក្រៅពីការវង្វេង? ដូច្នេះតើអ្នកត្រូវបានបង្វែរយ៉ាងដូចម្តេច? 10:32
- ភាគច្រើននៃពួកគេដើរតាមតែការស្មានប៉ុណ្ណោះ។ ពិតប្រាកដណាស់ ការស្មានមិនអាចជំនួសការពិតបានឡើយ។ 10:36
- ពិតប្រាកដណាស់! អល់ឡោះមិនដែលជិះជាន់មនុស្សឡើយ។ ប៉ុន្តែមនុស្សជាអ្នកជិះជាន់ខ្លួនឯងវិញ។ 10:44
- ចូរដឹងថាព្រះគុណរបស់ព្រះគឺប្រសើរជាងអ្វីៗទាំងអស់ដែលមនុស្សអាចប្រមូល ឬទុកដាក់បាន។ 10:58
- កុំក្លាយជាអ្នកដែលបដិសេធខគម្ពីររបស់អល់ឡោះ បើមិនដូច្នេះទេអ្នកនឹងក្លាយជាអ្នកខាតបង់។ 10:95
- ប្រសិនបើអល់ឡោះប៉ះពាល់អ្នកដោយគ្រោះថ្នាក់ គ្មានអ្នកណាអាចដកវាចេញបានឡើយ លើកលែងតែទ្រង់។ ហើយប្រសិនបើទ្រង់ចង់បានសេចក្តីល្អសម្រាប់អ្នក គ្មានអ្នកណាអាចរារាំងព្រះគុណរបស់ទ្រង់បានឡើយ ទ្រង់ប្រទានវាដល់អ្នកណាដែលទ្រង់សព្វព្រះទ័យក្នុងចំណោមពួកអ្នកបម្រើរបស់ទ្រង់។ 10:107
- គ្មានសត្វណាមួយនៅលើផែនដីដែលមិនមានចំណីអាហាររបស់វាពីអល់ឡោះឡើយ។ ហើយទ្រង់ជ្រាបពីទីលំនៅរបស់វា និងទីបញ្ចុះរបស់វា (ក្នុងស្បូន ផ្នូរ។ល។)។ 11:6
- ប្រសិនបើយើងឱ្យមនុស្សទទួលរសជាតិនៃសេចក្តីមេត្តាករុណាពីយើង រួចយើងដកវាចេញពីគាត់ នោះពិតប្រាកដណាស់ គាត់នឹងអស់សង្ឃឹម និងដឹងគុណ។ 11:9
- អ្នកណាដែលប្រាថ្នាចង់បានជីវិតនៅលោកិយ និងភាពរុងរឿងរបស់វា យើងនឹងប្រគល់ឱ្យពួកគេនូវរង្វាន់ពេញលេញនៃអំពើរបស់ពួកគេនៅក្នុងនោះ ហើយពួកគេនឹងមិនត្រូវបានបន្ថយឡើយ។ 11:15
- យើងមិនបានជិះជាន់ពួកគេទេ ប៉ុន្តែពួកគេជាអ្នកជិះជាន់ខ្លួនឯងវិញ។ ហើយអាទិទេពរបស់ពួកគេដែលពួកគេអង្វរករក្រៅពីអល់ឡោះ មិនបានផ្តល់ប្រយោជន៍អ្វីដល់ពួកគេឡើយ នៅពេលដែលបញ្ជារបស់ព្រះជាម្ចាស់របស់អ្នកបានមកដល់ ហើយពួកវាមិនបានបន្ថែមអ្វីដល់ពួកគេក្រៅពីការបំផ្លិចបំផ្លាញឡើយ។ 11:101
- នៅថ្ងៃដែលវា (ទណ្ឌកម្ម) មកដល់ គ្មានព្រលឹងណាមួយនឹងនិយាយឡើយ លើកលែងតែមានការអនុញ្ញាតពីទ្រង់ (អល់ឡោះ)។ ក្នុងចំណោមពួកគេ ខ្លះនឹងក្លាយជាអ្នកអកុសល និង (ខ្លះទៀត) ជាអ្នកមានសុភមង្គល។ 11:105
- ចំណែកអ្នកអកុសល ពួកគេនឹងនៅក្នុងភ្លើងនរក ដែលពួកគេនឹងថ្ងូរ និងគ្រហឹម។ 11:106
- ពួកគេនឹងស្ថិតនៅក្នុងនោះជារៀងរហូត ដរាបណាផ្ទៃមេឃ និងផែនដីនៅតែមាន លើកលែងតែព្រះជាម្ចាស់របស់អ្នកសព្វព្រះទ័យ។ ពិតប្រាកដណាស់ ព្រះជាម្ចាស់របស់អ្នក គឺជាអ្នកធ្វើនូវអ្វីដែលទ្រង់សព្វព្រះទ័យ។ 11:107
- ហើយអ្នកដែលមានសុភមង្គល ពួកគេនឹងនៅក្នុងស្ថានសួគ៌ ដោយស្ថិតនៅក្នុងនោះជារៀងរហូត ដរាបណាផ្ទៃមេឃ និងផែនដីនៅតែមាន លើកលែងតែព្រះជាម្ចាស់របស់អ្នកសព្វព្រះទ័យ ដែលជាអំណោយគ្មានទីបញ្ចប់។ 11:108
- កុំអនុគ្រោះដល់ពួកអយុត្តិធម៌ បើមិនដូច្នេះទេ ភ្លើងនរកនឹងប៉ះពាល់អ្នក ហើយអ្នកនឹងគ្មានអ្នកការពារក្រៅពីអល់ឡោះឡើយ ហើយបន្ទាប់មកអ្នកនឹងមិនត្រូវបានជួយឡើយ។ 11:113
- ចូរប្រតិបត្តិការអធិស្ឋាននៅចុងទាំងពីរនៃថ្ងៃ និងនៅពេលខ្លះនៃពេលយប់ (គឺការអធិស្ឋាន ៥ ដងក្នុងមួយថ្ងៃ)។ អំពើល្អៗនឹងលុបបំបាត់អំពើអាក្រក់ៗ (គឺអំពើបាបតូចតាច)។ 11:114
- អ្វីដែលមើលមិនឃើញនៅលើមេឃ និងផែនដីគឺសម្រាប់អល់ឡោះ ហើយរាល់កិច្ចការទាំងអស់ត្រូវបានប្រគល់ទៅឱ្យទ្រង់ (ដើម្បីសម្រេចចិត្ត)។ 11:123
- ការបញ្ជា (ឬការវិនិច្ឆ័យ) គឺសម្រាប់តែអល់ឡោះប៉ុណ្ណោះ។ ទ្រង់បានបញ្ជាឱ្យអ្នកគោរពបូជាតែទ្រង់ប៉ុណ្ណោះ (ជំនឿលើព្រះតែមួយ) នោះគឺជាសាសនាដ៏ត្រឹមត្រូវ ប៉ុន្តែមនុស្សភាគច្រើនមិនដឹងឡើយ។ 12:40
- កុំអស់សង្ឃឹមចំពោះសេចក្តីមេត្តាករុណារបស់អល់ឡោះឡើយ។ 12:87
- ហើយមនុស្សភាគច្រើននឹងមិនជឿ ទោះបីជាអ្នកប្រាថ្នាចង់បានយ៉ាងខ្លាំងក៏ដោយ។ 12:103
- ហើយភាគច្រើននៃពួកគេមិនជឿលើអល់ឡោះទេ លើកលែងតែពួកគេប្រព្រឹត្តពហុទេពនិយមជាមួយទ្រង់ (ឧ. ពួកគេជាពួកពហុទេពនិយម)។ 12:106
- វា (គម្ពីគួរអាន) មិនមែនជាពាក្យសំដីប្រឌិតទេ ប៉ុន្តែជាការបញ្ជាក់អំពីគម្ពីរដែលមានពីមុនរបស់អល់ឡោះ (គម្ពីរតូរ៉ា គម្ពីរអ៊ីនជីល និងគម្ពីរដទៃទៀតរបស់អល់ឡោះ) និងជាការពន្យល់យ៉ាងលម្អិតអំពីគ្រប់អ្វីៗទាំងអស់ ហើយជាការណែនាំ និងសេចក្តីមេត្តាករុណាសម្រាប់អ្នកដែលជឿ។ 12:111
- អល់ឡោះពង្រីកស្បៀងអាហារសម្រាប់អ្នកណាដែលទ្រង់សព្វព្រះទ័យ ហើយទ្រង់រួមតូច (សម្រាប់អ្នកណាដែលទ្រង់សព្វព្រះទ័យ)។ 13:26
- ចូរចងចាំអល់ឡោះជាញឹកញាប់តាមរយៈការរំលឹក។ អ្នកដែលជឿលើព្រះ ពួកគេស្វែងរកការពេញចិត្តនៅក្នុងការរំលឹកដល់ទ្រង់។ 13:28
- អ្នកដែលជឿ និងធ្វើអំពើល្អ ត្រូវបានផ្តល់នូវសេចក្តីរីករាយ និងសេចក្តីស្ងប់សុខនៃចិត្ត។ 13:29
- អ្នកដែលចូលចិត្តជីវិតនៅលោកិយជាងជីវិតបរលោក ហើយរារាំង (មនុស្ស) ពីមាគ៌ារបស់អល់ឡោះ (សាសនាឥស្លាម) ហើយស្វែងរកការបង្កែវង្វេងនៅក្នុងនោះ — ពួកគេស្ថិតនៅក្នុងការវង្វេងដ៏ឆ្ងាយ។ 14:3
- ចូរប្រតិបត្តិនូវភាពរាបទាប និងការដឹងគុណក្នុងការគោរពបូជា។ 14:7
- ឧទាហរណ៍នៃអ្នកដែលមិនជឿលើព្រះជាម្ចាស់របស់ពួកគេ គឺអំពើរបស់ពួកគេប្រៀបដូចជាផេះ ដែលខ្យល់បក់បោកយ៉ាងខ្លាំងនៅថ្ងៃមានខ្យល់ព្យុះ។ ពួកគេនឹងមិនអាចទទួលបានអ្វីពីអ្វីដែលពួកគេបានប្រព្រឹត្តឡើយ។ 14:18
- អល់ឡោះនឹងពង្រឹងអ្នកដែលជឿដោយពាក្យសម្តីដ៏មាំមួនក្នុងជីវិតនៅលោកិយនេះ (គឺពួកគេនឹងបន្តគោរពបូជាតែអល់ឡោះប៉ុណ្ណោះ) និងក្នុងជីវិតបរលោក។ 14:27
- កុំគិតថាអល់ឡោះមិនខ្វល់ពីអ្វីដែលពួកអយុត្តិធម៌ (ពួកពហុទេពនិយម ពួកជិះជាន់។ល។) កំពុងធ្វើនោះឡើយ។ ប៉ុន្តែទ្រង់ពន្យារពេលពួកគេទៅថ្ងៃដែលភ្នែកនឹងភ្លឺដោយភាពភ័យខ្លាច។ 14:42
- ដើម្បីឱ្យអល់ឡោះផ្តល់រង្វាន់ដល់គ្រប់ព្រលឹងតាមអ្វីដែលវាបានប្រព្រឹត្ត។ ពិតប្រាកដណាស់ អល់ឡោះគឺជាអ្នករហ័សក្នុងការតាំងគណនេយ្យ។ 14:51
- ហើយពិតប្រាកដណាស់ យើងបានបង្កើតមនុស្សចេញពីដីឥដ្ឋដែលមានសម្លេង ចេញពីភក់ខ្មៅដែលបានផ្លាស់ប្តូរ។ 15:26
- ហើយពួកជីន យើងបានបង្កើតពួកវាពីមុនមកពីភ្លើងដែលឆេៅក្តៅគ្មានផ្សែង។ 15:27
- វា (នរក) មានច្រកចំនួនប្រាំពីរ សម្រាប់ច្រកនីមួយៗមាន (ថ្នាក់ពិសេស) នៃពួកបាបជន។ 15:44
- ទ្រង់បានបង្កើតមនុស្សពីទឹកកាម (ល្បាយនៃទឹកកាមបុរស និងស្ត្រី) ហើយមើលចុះ គាត់ (មនុស្ស) បានក្លាយជាគូប្រជែងដ៏ច្បាស់លាស់។ 16:4
- ហើយសត្វចិញ្ចឹម ទ្រង់បានបង្កើតវាសម្រាប់អ្នក។ នៅក្នុងវាមានភាពកក់ក្តៅ (សម្លៀកបំពាក់ក្តៅ) និងអត្ថប្រយោជន៍ជាច្រើនសម្រាប់អ្នក ហើយពីវាអ្នកបរិភោគ។ 16:5
- ហើយ (ទ្រង់បានបង្កើត) សេះ លា និងសត្វកូនកាំបិត សម្រាប់អ្នកជិះ និងជាគ្រឿងតុបតែង។ ហើយទ្រង់បង្កើត (វត្ថុផ្សេងទៀត) ដែលអ្នកមិនដឹង។ 16:8
- ទ្រង់គឺជាអ្នកដែលបញ្ចុះទឹក (ភ្លៀង) ពីលើមេឃ។ ពីវាអ្នកផឹក ហើយពីវាដំណាំដុះឡើង ដែលអ្នកប្រើសម្រាប់ចិញ្ចឹមសត្វរបស់អ្នក។ 16:10
- ទ្រង់គឺជាអ្នកដែលបានបង្ក្រាបសមុទ្រ (សម្រាប់អ្នក) ដើម្បីឱ្យអ្នកអាចបរិភោគសាច់ស្រស់ (ត្រី) ពីវា និងដើម្បីឱ្យអ្នកអាចទាញយកគ្រឿងតុបតែងពីវាសម្រាប់ពាក់។ 16:14
- ទ្រង់បានដាក់ភ្នំដ៏រឹងមាំនៅលើផែនដី ដើម្បីកុំឱ្យវារង្គើជាមួយអ្នក ហើយ (ទ្រង់បានដាក់) ទន្លេ និងផ្លូវ ដើម្បីឱ្យអ្នកបានទទួលការណែនាំ។ 16:15
- តើអ្នកដែលបង្កើត ប្រៀបដូចអ្នកដែលមិនបង្កើតឬ? តើអ្នកមិនចាំទេឬ? 16:17
- ប្រសិនបើអ្នកព្យាយាមរាប់ព្រះគុណរបស់អល់ឡោះ អ្នកនឹងមិនអាចរាប់បានឡើយ។ 16:18
- អល់ឡោះដឹងពីអ្វីដែលអ្នកលាក់កំបាំង និងអ្វីដែលអ្នកបង្ហាញ។ 16:19
- អ្វីដែលពួកគេ (ពួកពហុទេពនិយម) អង្វរករក្រៅពីអល់ឡោះ មិនបានបង្កើតអ្វីទេ ប៉ុន្តែវាត្រូវបានបង្កើតឡើងវិញ។ 16:20
- (វាគឺជា) វត្ថុស្លាប់ គ្មានជីវិត ហើយពួកវាមិនដឹងថាពេលណាពួកវានឹងត្រូវបានគេប្រោសឱ្យរស់ឡើងវិញទេ។ 16:21
- ពាក្យសំដីរបស់យើងចំពោះវត្ថុណាមួយ នៅពេលដែលយើងចង់បានវា គឺគ្រាន់តែនិយាយទៅកាន់វាថា "ចូរកើតឡើង!" ហើយវាក៏កើតឡើង។ 16:40
- តើអ្នកដែលរៀបចំផែនការអាក្រក់ មានអារម្មណ៍សុវត្ថិភាពទេថា អល់ឡោះនឹងមិនធ្វើឱ្យពួកគេលិចចូលទៅក្នុងដី ឬថាទណ្ឌកម្មនឹងមិនមកដល់ពួកគេពីទិសដៅដែលពួកគេមិននឹកស្មាន? 16:45
- អ្វីដែលល្អ និងព្រះគុណណាដែលអ្នកមាន គឺមកពីអល់ឡោះ។ បន្ទាប់មកនៅពេលដែលគ្រោះថ្នាក់ប៉ះពាល់អ្នក អ្នកស្រែកអង្វររកជំនួយពីទ្រង់។ 16:53
- បន្ទាប់មកនៅពេលដែលទ្រង់បានបំបាត់គ្រោះថ្នាក់ពីអ្នក ស្រាប់តែមួយចំនួននៃអ្នកធ្វើពហុទេពនិយមជាមួយព្រះជាម្ចាស់របស់ពួកគេ (អល់ឡោះ)។ 16:54
- ក្នុងសត្វចិញ្ចឹម មានមេរៀនមួយសម្រាប់អ្នក។ យើងផ្តល់ឱ្យអ្នកនូវទឹកដោះដ៏បរិសុទ្ធ ដែលចេញពីពោះវៀនរបស់វា រវាងលាមក និងឈាម ដែលជាទឹកដោះដ៏ឈ្ងុយឆ្ងាញ់សម្រាប់អ្នកផឹក។ 16:66
- ដូច្នេះ កុំប្រៀបធៀបអល់ឡោះជាមួយអ្វីទាំងអស់ (ពីព្រោះគ្មានអ្វីប្រៀបបាននឹងទ្រង់ ហើយទ្រង់ក៏មិនប្រៀបដូចអ្វីដែរ)។ ពិតប្រាកដណាស់ អល់ឡោះដឹង ហើយអ្នកមិនដឹង។ 16:74
- ចូរដឹងថា ព្រះបានប្រទានឱ្យមនុស្សនូវការស្តាប់ ការមើលឃើញ បញ្ញា និងអារម្មណ៍ ដើម្បីឱ្យពួកគេដឹងគុណ។ 16:78
- ចូរចៀសវាងពីភាពលោភលន់ និងកំណាញ់។ 16:97
- នៅពេលដែលអ្នកចង់សូត្រគម្ពីគួរអាន ចូរស្វែងរកទីពឹងជ្រកក្នុងអល់ឡោះពីស្ហៃតាន ដែលត្រូវបានគេបណ្តេញចេញ។ 16:98
- ចូរដឹងថាកំហុសដែលបានប្រព្រឹត្តដោយភាពល្ងង់ខ្លៅ ត្រូវបានអភ័យទោស ប្រសិនបើបុគ្គលនោះប្រែចិត្ត និងកែខ្លួនឯង។ 16:119
- ចូរអំពាវនាវ (ឱមូហាំម៉ាត់ ﷺ) ទៅកាន់មាគ៌ារបស់ព្រះជាម្ចាស់របស់អ្នក (សាសនាឥស្លាម) ដោយប្រាជ្ញា និងការផ្សើមផ្សាយដ៏ល្អ ហើយចូរជជែកដេញដោលជាមួយពួកគេតាមរបៀបដែលល្អបំផុត។ ការអំពាវនាវអ្នកដទៃទៅកាន់មាគ៌ារបស់ព្រះ គួរតែធ្វើដោយប្រាជ្ញា និងភាពសប្បុរស។ 16:125
- អល់ឡោះគង់នៅជាមួយអ្នកដែលកោតខ្លាចទ្រង់ (អ្នកដែលបំពេញកាតព្វកិច្ចរបស់ពួកគេចំពោះទ្រង់) និងអ្នកដែលធ្វើអំពើល្អ។ 16:128
- គម្ពីគួរអាននេះណែនាំទៅកាន់អ្វីដែលត្រឹមត្រូវ និងយុត្តិធម៌បំផុត។ 17:9
- គ្មាននរណាម្នាក់អាចទទួលបន្ទុកអំពើបាបរបស់អ្នកដទៃបានឡើយ។ 17:15
- អ្នកណាដែលប្រាថ្នាចង់បានជីវិតបរលោក ហើយខិតខំប្រឹងប្រែងសម្រាប់វា ដោយការខិតខំប្រឹងប្រែងដ៏សមស្រប ហើយគាត់ជាអ្នកជឿ នោះអ្នកទាំងនោះ ការខិតខំប្រឹងប្រែងរបស់ពួកគេនឹងត្រូវបានគេទទួលស្គាល់ និងផ្តល់រង្វាន់ (ដោយអល់ឡោះ)។ 17:19
- ចូរគោរពឪពុកម្តាយរបស់អ្នក ហើយប្រព្រឹត្តចំពោះពួកគេដោយសេចក្តីសប្បុរស។ ចូរគោរពតាមឪពុកម្តាយ។ កុំនិយាយពាក្យមិនគោរពទៅកាន់ឪពុកម្តាយ។ ហើយព្រះជាម្ចាស់របស់អ្នកបានបញ្ជាថា អ្នកមិនត្រូវគោរពបូជាអ្នកណាក្រៅពីទ្រង់ឡើយ។ ហើយចូរធ្វើល្អចំពោះឪពុកម្តាយ។ ប្រសិនបើពួកគេម្នាក់ ឬទាំងពីរមានវ័យចំណាស់នៅក្បែរអ្នក កុំនិយាយទៅកាន់ពួកគេថា "អឺយ" ហើយកុំស្តីបន្ទោសពួកគេ ប៉ុន្តែចូរនិយាយទៅកាន់ពួកគេដោយពាក្យសំដីប្រកបដោយកិត្តិយស។ 17:23
- ហើយចូរបន្ទាបស្លាបនៃភាពរាបទាប និងសេចក្តីមេត្តាករុណាចំពោះពួកគេ ហើយនិយាយថា: "ឱព្រះជាម្ចាស់របស់ទូកខ្ញុំ! សូមទ្រង់មេត្តាប្រោសពួកគេ ដូចដែលពួកគេបានចិញ្ចឹមទូកខ្ញុំកាលពីតូច។" 17:24
- ពិតប្រាកដណាស់ អ្នកខ្ជះខ្ជាយគឺជាបងប្អូននៃពួកស្ហៃតាន ហើយស្ហៃតានគឺជាអ្នកដែលរឹងរូសមិនដឹងគុណចំពោះព្រះជាម្ចាស់របស់វា។ 17:27
- កុំខ្ជះខ្ជាយលុយកាក់។ 17:29
- កុំសម្លាប់កូនរបស់អ្នកដោយសារតែការភ័យខ្លាចភាពក្រីក្រ។ 17:31
- កុំចូលទៅជិតអំពើសហាយស្មន់។ ចូររក្សាភាពពិសិដ្ឋនៃអាពាហ៍ពិពាហ៍ ហើយចៀសវាងអំពើសហាយស្មន់។ 17:32
- ចូរប្រគល់រង្វាស់ពេញលេញនៅពេលអ្នកវាស់ ហើយចូរថ្លឹងដោយជញ្ជីងត្រឹមត្រូវ។ នោះគឺល្អ (មានប្រយោជន៍) ហើយប្រសើរជាងនៅទីបញ្ចប់។ 17:35
- កុំដើរតាម (ឱមនុស្ស គឺកុំនិយាយ កុំធ្វើ ឬកុំធ្វើជាសាក្សី។ល។) អ្វីដែលអ្នកមិនមានចំណេះដឹងអំពីវា (ឧ. ការនិយាយថា "ខ្ញុំបានឃើញ" ខណៈដែលគាត់មិនបានឃើញ ឬ "ខ្ញុំបានឮ" ខណៈដែលគាត់មិនបានឮ)។ 17:36
- ចូររាបទាប ហើយកុំក្រអឺតក្រទម។ កុំដើរលើផែនដីដោយក្រអឺតក្រទម និងអំនួត។ ពិតប្រាកដណាស់ អ្នកមិនអាចធ្វើឱ្យផែនដីរបកចេញបានទេ ហើយអ្នកក៏មិនអាចឈានដល់កម្ពស់ភ្នំបានដែរ។ 17:37
- ព្រះជាម្ចាស់របស់អ្នកជ្រាបច្បាស់ពីអ្នក។ ប្រសិនបើទ្រង់សព្វព្រះទ័យ ទ្រង់នឹងមេត្តាអ្នក។ ហើយប្រសិនបើទ្រង់សព្វព្រះទ័យ ទ្រង់នឹងផ្តន្ទាទោសអ្នក។ 17:54
- អ្នកណាដែលខ្វាក់ភ្នែកក្នុងលោកិយនេះ (គឺមិនបានឃើញទីសំគាល់របស់អល់ឡោះ និងមិនជឿលើទ្រង់) គាត់នឹងខ្វាក់ភ្នែកក្នុងជីវិតបរលោក ហើយកាន់តែវង្វេងចេញពីមាគ៌ា។ 17:72
- ចូរប្រតិបត្តិការអធិស្ឋានតាមពេលវេលាដែលបានកំណត់។ 17:78
- ពិតប្រាកដណាស់ យើងបានពន្យល់ដល់មនុស្សយ៉ាងច្រើននៅក្នុងគម្ពីគួរអាននេះ នូវគ្រប់ប្រភេទនៃឧទាហរណ៍ ប៉ុន្តែមនុស្សភាគច្រើនបដិសេធ (ការពិត) ហើយមិនទទួលយកអ្វីក្រៅពីការមិនជឿឡើយ។ 17:89
- យើងបានបង្ហាញគ្រប់ប្រភេទនៃឧទាហរណ៍នៅក្នុងគម្ពីគួរអាននេះសម្រាប់មនុស្ស។ ប៉ុន្តែមនុស្សគឺជាអ្នកឈ្លោះប្រកែកជាងអ្វីៗទាំងអស់។ 18:54
